INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(64, 'El Spa de Malvaviscos', 'The Marshmallow Spa', 'Tras una larga noche de travesuras, nuestro elfo ha decidido tomarse un merecido descanso. Se encuentra sumergido en una taza de cerámica gigante, rodeado de una "espuma" esponjosa hecha de mini nubes, simulando un relajante baño de burbujas térmico en pleno Polo Norte.' || char(10) || char(10) || 'Para esta manualidad necesitarás una taza de café grande, una bolsa de mini malvaviscos (nubes) y, opcionalmente, un trozo de tela azul para simular el agua bajo las nubes. Coloca al elfo con los brazos apoyados en el borde para mayor realismo. Tiempo estimado de creación: 5 minutos.', 'After a long night of mischief, our elf has decided to take a well-deserved break. He is submerged in a giant ceramic mug, surrounded by a fluffy "foam" made of mini marshmallows, simulating a relaxing thermal bubble bath right at the North Pole.' || char(10) || char(10) || 'For this craft you will need a large coffee mug, a bag of mini marshmallows and, optionally, a piece of blue fabric to simulate water beneath the marshmallows. Place the elf with his arms resting on the rim for added realism. Estimated creation time: 5 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(134, 'Misión Imposible: Rayos Láser', 'Mission Impossible: Laser Beams', 'El elfo se ha convertido en un agente secreto de alto riesgo. Ha sido interceptado en el pasillo intentando cruzar un sistema de seguridad infrarrojo compuesto por hilos rojos que se cruzan en todas direcciones. Su pose es acrobática, suspendido en el aire para evitar tocar el suelo.' || char(10) || char(10) || 'Materiales necesarios: Lana roja o hilo grueso de color llamativo, cinta adhesiva para fijar los hilos a las paredes del pasillo y un poco de hilo de pescar para colgar al elfo del techo de forma invisible. Tiempo estimado de creación: 20 minutos.', 'The elf has become a high-risk secret agent. He has been intercepted in the hallway trying to cross an infrared security system made of red strings crisscrossing in all directions. His pose is acrobatic, suspended in mid-air to avoid touching the floor.' || char(10) || char(10) || 'Materials needed: red yarn or thick brightly colored string, adhesive tape to fix the strings to the hallway walls, and a bit of fishing line to hang the elf invisibly from the ceiling. Estimated creation time: 20 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(110, 'El Iglú de Ingeniería Ártica', 'The Arctic Engineering Igloo', 'Nuestro pequeño arquitecto ha pasado la noche construyendo un refugio resistente al frío. Se trata de un iglú perfectamente estructurado bloque a bloque, donde el elfo asoma la cabeza por la puerta principal, listo para protegerse de cualquier ventisca navideña en la cocina.' || char(10) || char(10) || 'Necesitarás una bolsa grande de malvaviscos blancos de tamaño normal y una pistola de silicona fría o glaseado denso para unir las piezas. Usa un tazón de base para darle la forma circular inicial y luego retíralo. Tiempo estimado de creación: 45 minutos.', 'Our little architect has spent the night building a cold-resistant shelter. It is a perfectly structured igloo built block by block, with the elf poking his head through the main entrance, ready to shield himself from any Christmas blizzard in the kitchen.' || char(10) || char(10) || 'You will need a large bag of regular-sized white marshmallows and a cold glue gun or thick icing to join the pieces. Use a bowl as a base to shape the initial circle, then remove it. Estimated creation time: 45 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"KITCHEN"},{"label":"HARD"}]', 0),
(135, 'Pesca Milagrosa en el Lavabo', 'Miraculous Fishing in the Sink', 'El instinto de supervivencia ha llevado al elfo a las orillas del lavabo principal. Con una caña de pescar artesanal, intenta capturar unos peces dorados que nadan en las profundidades de la cerámica, mientras descansa cómodamente sentado sobre un rollo de papel higiénico.' || char(10) || char(10) || 'Materiales: Un palito de brocheta, hilo dental para el sedal y galletas con forma de pez o recortes de cartulina naranja. Puedes usar papel de seda azul en el fondo del lavabo para simular el agua sin usar líquido real. Tiempo estimado de creación: 10 minutos.', 'The survival instinct has led the elf to the shores of the main bathroom sink. With a handmade fishing rod, he tries to catch golden fish swimming in the depths of the ceramic basin, while resting comfortably on a toilet paper roll.' || char(10) || char(10) || 'Materials: a skewer stick, dental floss for the fishing line, and fish-shaped crackers or orange cardstock cutouts. You can use blue tissue paper at the bottom of the sink to simulate water without using real liquid. Estimated creation time: 10 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(76, 'Campamento Bajo las Estrellas', 'Camping Under the Stars', 'El elfo ha montado su propia zona de acampada en el dormitorio. Ha fabricado una tienda de campaña de estilo "tepee" y ha encendido una fogata acogedora donde se está calentando las manos mientras espera que amanezca para seguir con sus vigilancias.' || char(10) || char(10) || 'Necesitarás un pañuelo grande o trozo de fieltro, tres lápices para la estructura de la tienda, y unos palitos de canela para la hoguera. Usa una vela de té LED (sin llama real) para darle ese brillo cálido de noche de campo. Tiempo estimado de creación: 15 minutos.', 'The elf has set up his own camping area in the bedroom. He has made a tepee-style tent and lit a cozy campfire where he is warming his hands while waiting for dawn to continue his watch duties.' || char(10) || char(10) || 'You will need a large handkerchief or piece of felt, three pencils for the tent frame, and some cinnamon sticks for the campfire. Use an LED tea candle (no real flame) to give it that warm glow of an outdoor night. Estimated creation time: 15 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"FOREST"},{"label":"MEDIUM"}]', 0),
(62, 'Búsqueda del Tesoro de Oro', 'The Golden Treasure Hunt', '¡Ha aparecido un cofre misterioso! El elfo ha encontrado un escondite secreto lleno de monedas de oro y ahora las está custodiando con recelo. Ha dejado un rastro de pistas brillantes por toda la habitación para que los niños encuentren el camino hacia el botín.' || char(10) || char(10) || 'Materiales: Una cajita de madera o cartón decorada, monedas de chocolate envueltas en papel dorado y un poco de purpurina para el rastro. No olvides escribir un pequeño mapa con papel envejecido con café. Tiempo estimado de creación: 20 minutos.', 'A mysterious chest has appeared! The elf has found a secret hiding spot full of gold coins and is now guarding them jealously. He has left a trail of glittering clues all around the room for the kids to follow the path to the loot.' || char(10) || char(10) || 'Materials: a small decorated wooden or cardboard box, chocolate coins wrapped in gold foil, and a little glitter for the trail. Don''t forget to write a small map on paper aged with coffee. Estimated creation time: 20 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(131, 'Desfile de Moda: La Momia', 'Fashion Show: The Mummy', 'Las travesuras en el vestidor han ido demasiado lejos. El elfo intentó probarse todos los calcetines de la casa pero acabó enredándose accidentalmente en un rollo de vendas, transformándose en una pequeña y simpática momia navideña que apenas puede caminar.' || char(10) || char(10) || 'Solo necesitas un rollo de gasa médica o papel higiénico. Envuelve al elfo de forma caótica dejando que algunos hilos cuelguen por el suelo del armario o el cajón de la ropa. Tiempo estimado de creación: 5 minutos.', 'The dressing room antics have gone too far. The elf tried on every sock in the house but ended up accidentally tangled in a roll of bandages, transforming into a cute little Christmas mummy that can barely walk.' || char(10) || char(10) || 'All you need is a roll of medical gauze or toilet paper. Wrap the elf chaotically, letting some threads hang down onto the wardrobe floor or clothing drawer. Estimated creation time: 5 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"DANGER"},{"label":"EASY"}]', 0),
(40, 'Cine de Juguetes Navideño', 'Christmas Toy Cinema', 'Es noche de estreno en el salón. El elfo ha organizado una función de cine para todos los peluches de la casa. Están sentados en filas perfectas frente a una "pantalla" (una tablet o móvil) con un enorme cubo de palomitas recién hechas para compartir.' || char(10) || char(10) || 'Materiales: Un bol pequeño con palomitas de maíz reales, tus figuras de acción favoritas y un dispositivo para reproducir una película corta. Esparce algunas palomitas por el suelo para darle ese toque de realismo de sala de cine. Tiempo estimado de creación: 10 minutos.', 'It is premiere night in the living room. The elf has organized a movie screening for all the stuffed animals in the house. They are seated in perfect rows in front of a "screen" (a tablet or phone) with a huge bucket of freshly made popcorn to share.' || char(10) || char(10) || 'Materials: a small bowl with real popcorn, your favorite action figures, and a device to play a short movie. Scatter some popcorn on the floor to add that authentic movie theater feel. Estimated creation time: 10 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"FESTIVAL"},{"label":"EASY"}]', 0),
(41, 'El Robo del Tarro de Dulces', 'The Candy Jar Heist', 'El elfo ha sido pillado "in fraganti" intentando escalar el tarro de cristal de las golosinas. Se encuentra colgado de la tapa con una mano, mientras con la otra intenta alcanzar un bastón de caramelo especialmente grande que brilla en el interior.' || char(10) || char(10) || 'Necesitarás un tarro de cristal transparente lleno de caramelos coloridos y un poco de masilla adhesiva o celo de doble cara para fijar la mano del elfo al borde del tarro, simulando que se está resbalando. Tiempo estimado de creación: 5 minutos.', 'The elf has been caught red-handed trying to climb the glass candy jar. He is hanging from the lid with one hand, while with the other he tries to reach an especially large candy cane that gleams inside.' || char(10) || char(10) || 'You will need a transparent glass jar full of colorful candies and a little adhesive putty or double-sided tape to fix the elf''s hand to the edge of the jar, as if he is slipping. Estimated creation time: 5 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"TREASURE"},{"label":"EASY"}]', 0),
(39, 'Carrera de Trineos de Escalera', 'Staircase Sled Race', 'La barandilla de la escalera se ha convertido en una pista de bobsleigh olímpica. El elfo se ha fabricado un trineo de alta velocidad con bastones de caramelo y está descendiendo a toda prisa, con su bufanda volando hacia atrás por la inercia del movimiento.' || char(10) || char(10) || 'Materiales: Dos bastones de caramelo reales para los patines, una cajita de cerillas vacía para el asiento del trineo y un trozo de lana roja para la bufanda. Sujeta el conjunto a la barandilla con cinta adhesiva transparente. Tiempo estimado de creación: 15 minutos.', 'The stair railing has become an Olympic bobsled track. The elf has built a high-speed sled from candy canes and is racing downward at full speed, his scarf flying back from the momentum of the movement.' || char(10) || char(10) || 'Materials: two real candy canes for the runners, an empty matchbox for the sled seat, and a piece of red yarn for the scarf. Attach the whole thing to the railing with clear adhesive tape. Estimated creation time: 15 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"FESTIVAL"},{"label":"MEDIUM"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(66, 'El Banquete Real de Mini-Tortitas', 'The Royal Mini-Pancake Banquet', '¡El elfo se ha despertado con un hambre voraz y ha decidido montar un desayuno de lujo directamente sobre la mesita de noche! Ha preparado una torre de tortitas minúsculas del tamaño de una moneda, decoradas con un chorrito de sirope y una pizca de azúcar glass, mientras espera pacientemente a que los niños despierten para compartir su festín.' || char(10) || char(10) || 'Para esta manualidad necesitarás masa de tortitas real (solo una gota por unidad), un tapón de botella que sirva como plato miniatura y un trozo de papel para simular una servilleta de tela. Es una escena encantadora para el dormitorio. Tiempo estimado de creación: 15 minutos.', 'The elf has woken up absolutely starving and decided to set up a luxury breakfast right on the bedside table! He has prepared a tower of tiny coin-sized pancakes, decorated with a drizzle of syrup and a sprinkle of powdered sugar, patiently waiting for the kids to wake up and share his feast.' || char(10) || char(10) || 'For this craft you will need real pancake batter (just one drop per unit), a bottle cap as a miniature plate, and a piece of paper to simulate a cloth napkin. It is a charming scene for the bedroom. Estimated creation time: 15 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(86, 'Pesca de Altura en el Gran Lavabo', 'High-Altitude Fishing in the Big Sink', 'Nuestro aventurero ha encontrado el "lago de porcelana" en el baño y no ha podido resistir la tentación de ir de pesca. Sentado en el borde del lavabo con una caña de pescar improvisada, el elfo intenta capturar unos peces de colores que parecen haber aparecido mágicamente durante la noche en el agua cristalina.' || char(10) || char(10) || 'Necesitarás un palito de brocheta, hilo dental para el sedal y unas cuantas galletas con forma de pez (tipo Goldfish) o recortes de cartulina. Puedes añadir un poco de colorante azul al agua para un efecto más realista. Tiempo estimado de creación: 10 minutos.', 'Our adventurer has discovered the "porcelain lake" in the bathroom and could not resist the urge to go fishing. Sitting on the edge of the sink with an improvised fishing rod, the elf tries to catch colorful fish that seem to have magically appeared overnight in the crystal-clear water.' || char(10) || char(10) || 'You will need a skewer stick, dental floss for the fishing line, and a few fish-shaped crackers (like Goldfish) or cardstock cutouts. You can add a little blue food coloring to the water for a more realistic effect. Estimated creation time: 10 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(1, 'Ángel de Nieve en la Ventisca de Harina', 'Snow Angel in the Flour Blizzard', 'El elfo extraña tanto el Polo Norte que ha decidido recrear una tormenta de nieve en plena encimera de la cocina. Ha esparcido una capa uniforme de "nieve" blanca y se ha tumbado para crear un ángel perfecto, dejando sus huellas por todo el mostrador como prueba de su diversión nocturna.' || char(10) || char(10) || 'Materiales necesarios: Harina de trigo o azúcar glass, una bandeja para contener el desorden y un tamizador para esparcir el polvo de forma homogénea. Simplemente mueve los brazos del elfo de lado a lado sobre la harina. Tiempo estimado de creación: 10 minutos.', 'The elf misses the North Pole so much that he has decided to recreate a snowstorm right on the kitchen counter. He has spread a uniform layer of "snow" and lay down to make a perfect angel, leaving his tracks all over the counter as proof of his nightly fun.' || char(10) || char(10) || 'Materials needed: wheat flour or powdered sugar, a tray to contain the mess, and a sifter to spread the powder evenly. Simply move the elf''s arms from side to side over the flour. Estimated creation time: 10 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(142, 'El Prisionero de la Batidora', 'The Blender Prisoner', '¡Oh no! La curiosidad casi mata al elfo. Se ha quedado atrapado dentro de la batidora de vaso mientras intentaba investigar cómo se hacían los batidos navideños. Se le ve pegado al cristal con un cartel de "¡Socorro!" escrito a mano, rodeado de confeti y serpentinas que intentó usar para decorar el interior.' || char(10) || char(10) || 'Para esta escena solo necesitas la batidora (desenchufada por seguridad), un poco de confeti de colores y un trozo de papel pequeño para el cartel. Asegúrate de que el elfo esté bien visible a través del cristal. Tiempo estimado de creación: 5 minutos.', 'Oh no! Curiosity almost got the better of the elf. He got trapped inside the blender jug while trying to investigate how Christmas smoothies were made. He can be seen pressed against the glass with a handwritten "Help!" sign, surrounded by confetti and streamers he tried to use to decorate the interior.' || char(10) || char(10) || 'For this scene all you need is the blender (unplugged for safety), a little colorful confetti, and a small piece of paper for the sign. Make sure the elf is clearly visible through the glass. Estimated creation time: 5 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(96, 'El Enigma del Mapa del Tesoro', 'The Treasure Map Enigma', 'Un misterio ha llegado al salón. El elfo sostiene un pergamino envejecido que muestra un plano detallado de la planta baja con una gran "X" roja marcada detrás de las cortinas. Ha dejado una lupa de juguete al lado para que los niños le ayuden a descifrar las pistas que llevan a un botín escondido.' || char(10) || char(10) || 'Necesitarás una hoja de papel blanco, una bolsa de té húmeda para envejecer el papel, un mechero para quemar ligeramente los bordes y monedas de chocolate envueltas en oro para el tesoro final. Tiempo estimado de creación: 20 minutos.', 'A mystery has arrived in the living room. The elf is holding an aged parchment showing a detailed floor plan of the ground floor with a large red "X" marked behind the curtains. He has left a toy magnifying glass beside it for the kids to help him decode the clues leading to a hidden treasure.' || char(10) || char(10) || 'You will need a sheet of white paper, a wet tea bag to age the paper, a lighter to gently burn the edges, and chocolate coins wrapped in gold foil for the final treasure. Estimated creation time: 20 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"MYSTERY"},{"label":"LIVINGROOM"}]', 0),
(33, 'Desfile de Calcetines Navideños', 'Christmas Sock Parade', '¡El elfo se ha vuelto loco con la decoración! Ha decidido que los adornos del árbol de Navidad no eran suficientes y ha colgado todos los calcetines de colores de los niños por las ramas. Se le encuentra en la cima del árbol, con un calcetín puesto a modo de saco, repartiendo alegría (y algo de desorden) textil.' || char(10) || char(10) || 'Materiales: Varios pares de calcetines de colores, pinzas de la ropa pequeñas o clips para sujetarlos a las ramas del árbol y, por supuesto, el propio árbol de Navidad. Tiempo estimado de creación: 15 minutos.', 'The elf has gone decoration-crazy! He decided the Christmas tree ornaments were not enough and hung all the kids'' colorful socks on the branches. He can be found at the top of the tree wearing a sock as a bag, spreading joy (and a bit of textile chaos).' || char(10) || char(10) || 'Materials: several pairs of colorful socks, small clothespins or clips to hang them on the tree branches, and of course the Christmas tree itself. Estimated creation time: 15 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"FESTIVAL"},{"label":"MEDIUM"}]', 0),
(132, 'Tirolina Extrema de Salón', 'Extreme Living Room Zip Line', 'Para el elfo, el salón es un parque de atracciones. Ha montado una tirolina que cruza de una estantería al árbol de Navidad utilizando un bastón de caramelo como polea. Está congelado en el tiempo justo en mitad del descenso, con su bufanda volando (gracias a un alambre oculto).' || char(10) || char(10) || 'Necesitarás cordel resistente o hilo de pescar, un bastón de caramelo real y cinta adhesiva fuerte para los anclajes. Es fundamental tensar bien la cuerda para que el elfo no se deslice hacia abajo. Tiempo estimado de creación: 30 minutos.', 'For the elf, the living room is an amusement park. He has set up a zip line crossing from a bookshelf to the Christmas tree using a candy cane as a pulley. He is frozen in time right in the middle of the descent, his scarf flying (thanks to a hidden wire).' || char(10) || char(10) || 'You will need strong rope or fishing line, a real candy cane, and strong adhesive tape for the anchors. It is essential to pull the rope taut so the elf does not slide down. Estimated creation time: 30 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"HARD"}]', 0),
(19, 'Escondite en la Montaña de Colada', 'Hideout in the Laundry Mountain', 'Después de una noche agotadora, el elfo ha encontrado el lugar más suave y cálido de la casa: el cesto de la ropa recién salida de la secadora. Se ha enterrado entre toallas y camisetas blancas, dejando solo su gorro rojo asomando como si fuera un volcán en una cordillera de algodón.' || char(10) || char(10) || 'Solo necesitas un cesto de ropa y varias prendas blancas o suaves. Coloca al elfo en el fondo y ve añadiendo ropa encima con cuidado hasta que solo se vea la punta de su sombrero. Tiempo estimado de creación: 5 minutos.', 'After an exhausting night, the elf has found the softest and warmest spot in the house: the laundry basket fresh out of the dryer. He has buried himself among towels and white t-shirts, leaving only his red hat peeking out like a volcano in a cotton mountain range.' || char(10) || char(10) || 'All you need is a laundry basket and several white or soft garments. Place the elf at the bottom and carefully pile clothes on top until only the tip of his hat is visible. Estimated creation time: 5 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(84, 'El Código Secreto de la Caja Fuerte', 'The Secret Safe Code', 'Un gran misterio rodea al elfo esta mañana. Está sentado frente a una caja cerrada con un candado de juguete y sostiene una serie de acertijos matemáticos que los niños deben resolver para obtener la combinación. Dentro de la caja, el brillo del "tesoro" se intuye por las rendijas.' || char(10) || char(10) || 'Materiales: Una caja pequeña (puede ser de zapatos), un candado o cinta adhesiva simulándolo, papel y rotuladores para las pistas. Puedes esconder dulces o un juguete pequeño dentro. Tiempo estimado de creación: 40 minutos.', 'A great mystery surrounds the elf this morning. He is sitting in front of a locked box with a toy padlock, holding a series of math riddles that the kids must solve to get the combination. Inside the box, the gleam of the "treasure" can be glimpsed through the cracks.' || char(10) || char(10) || 'Materials: a small box (a shoe box works great), a padlock or tape to simulate one, paper and markers for the clues. You can hide candy or a small toy inside. Estimated creation time: 40 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"TREASURE"},{"label":"HARD"}]', 0),
(31, 'Atrapado en la Cascada de Burbujas', 'Trapped in the Bubble Waterfall', 'Una travesura en el baño que se fue de las manos. El elfo intentó darse un baño de burbujas pero usó demasiado jabón y ahora una "cascada" de espuma (algodón) desborda del lavabo hasta el suelo. El elfo está nadando entre la espuma con unas gafas de buceo hechas de cartulina.' || char(10) || char(10) || 'Necesitarás una bolsa grande de bolas de algodón o nubes de azúcar blancas, jabón de manos para el aroma y cartulina para las gafas de buceo. Pega el algodón con cinta de doble cara para crear el efecto de desbordamiento. Tiempo estimado de creación: 25 minutos.', 'A bathroom prank that got completely out of hand. The elf tried to take a bubble bath but used way too much soap, and now a "waterfall" of foam (cotton) is overflowing from the sink all the way to the floor. The elf is swimming through the foam wearing goggles made of cardstock.' || char(10) || char(10) || 'You will need a large bag of cotton balls or white sugar marshmallows, hand soap for the scent, and cardstock for the goggles. Stick the cotton with double-sided tape to create the overflow effect. Estimated creation time: 25 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"DANGER"},{"label":"HARD"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(120, 'Vuelo en Globo de Chuches', 'Candy Hot Air Balloon Flight', '¡El elfo ha decidido surcar los cielos del salón! Ha construido un globo aeroestático improvisado usando un globo inflado y una cesta de mimbre pequeña. Se encuentra suspendido cerca de una lámpara, saludando desde las alturas mientras "observa" quién se porta bien desde una perspectiva privilegiada.' || char(10) || char(10) || 'Para esta manualidad necesitarás un globo de helio (o uno normal pegado al techo con celo), una cesta pequeña o un vaso de papel decorado, y cuatro hilos de lana para unir el globo a la barquilla. Coloca algunos caramelos dentro para que parezca que lleva provisiones. Tiempo estimado de creación: 15 minutos.', 'The elf has decided to soar through the living room skies! He has built an improvised hot air balloon using an inflated balloon and a small wicker basket. He is suspended near a lamp, waving from the heights while "observing" who is behaving from a privileged vantage point.' || char(10) || char(10) || 'For this craft you will need a helium balloon (or a regular one taped to the ceiling), a small basket or decorated paper cup, and four yarn strings to connect the balloon to the basket. Place some candy inside so it looks like he is carrying provisions. Estimated creation time: 15 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(133, 'Spa de Nubes Tostadas', 'Toasted Marshmallow Spa', 'Después de tanto viaje, el elfo se está dando un capricho en la cocina. Ha montado un pequeño campamento de lujo donde está "tostando" malvaviscos sobre una vela electrónica. Está sentado en una esponja de cocina, envuelto en una servilleta a modo de albornoz, disfrutando de un momento de paz antes del caos matutino.' || char(10) || char(10) || 'Materiales necesarios: Una vela LED de té (importante: sin fuego real), palillos de dientes, mini malvaviscos y una servilleta blanca. Puedes usar un posavasos como alfombra para delimitar su zona de relax. Tiempo estimado de creación: 10 minutos.', 'After so much traveling, the elf is treating himself in the kitchen. He has set up a little luxury camp where he is "toasting" marshmallows over an electric candle. He is sitting on a kitchen sponge, wrapped in a napkin as a bathrobe, enjoying a moment of peace before the morning chaos.' || char(10) || char(10) || 'Materials needed: an LED tea candle (important: no real flame), toothpicks, mini marshmallows, and a white napkin. You can use a coaster as a rug to define his relaxation zone. Estimated creation time: 10 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(73, 'Barba de Nieve en el Espejo', 'Snow Beard in the Mirror', '¡Travesura en el baño! El elfo se ha levantado con ganas de un cambio de look y ha intentado afeitarse frente al espejo principal. Se ha cubierto la cara con espuma de afeitar (o nata montada) y ha dejado un mensaje gracioso escrito en el cristal, rodeado de huellas blancas por todo el lavabo.' || char(10) || char(10) || 'Necesitarás espuma de afeitar, un palito de helado que haga de cuchilla y un rotulador de tiza líquida para escribir en el espejo. Asegúrate de poner solo un poco de espuma en la cara del elfo para no estropear el fieltro. Tiempo estimado de creación: 5 minutos.', 'Bathroom prank! The elf woke up in the mood for a new look and tried to shave in front of the main mirror. He has covered his face with shaving foam (or whipped cream) and left a funny message written on the glass, surrounded by white prints all over the sink.' || char(10) || char(10) || 'You will need shaving foam, a popsicle stick as a razor, and a liquid chalk marker to write on the mirror. Make sure to put only a tiny bit of foam on the elf''s face to avoid ruining the felt. Estimated creation time: 5 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"EASY"}]', 0),
(124, 'El Laberinto de Lana', 'The Yarn Labyrinth', 'Un misterio ha bloqueado la entrada al dormitorio de los niños. El elfo ha pasado la noche tejiendo una red gigante de lana que cruza el marco de la puerta de lado a lado, como si fuera una tela de araña láser. Él está en el centro, sosteniendo el ovillo y desafiando a todos a pasar sin tocar los hilos.' || char(10) || char(10) || 'Para este montaje necesitarás un ovillo de lana (el rojo queda muy bien como "láser") y cinta adhesiva que no dañe el marco de la puerta. Cruza los hilos en diferentes ángulos y alturas para crear un verdadero reto físico. Tiempo estimado de creación: 20 minutos.', 'A mystery has blocked the entrance to the children''s bedroom. The elf spent the night weaving a giant yarn web across the entire door frame from side to side, like a laser spider web. He is in the center holding the ball of yarn, daring everyone to get through without touching the strings.' || char(10) || char(10) || 'For this setup you will need a ball of yarn (red works great as a "laser") and tape that won''t damage the door frame. Cross the strings at different angles and heights to create a real physical challenge. Estimated creation time: 20 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"BEDROOM"},{"label":"HARD"}]', 0),
(129, 'La Búsqueda del Tesoro Congelado', 'The Frozen Treasure Hunt', '¡El elfo ha traído un trozo del Polo Norte! Ha escondido varias monedas de chocolate dentro de un bloque de hielo que ha dejado en el fregadero. Junto a él, hay una pequeña nota con instrucciones sobre cómo los niños deben usar "herramientas" (agua templada y sal) para rescatar el botín atrapado.' || char(10) || char(10) || 'Materiales: Un recipiente con agua congelada previamente con monedas o juguetes dentro, y una bandeja para evitar derrames. Es una actividad sensorial increíble que mantendrá a los niños entretenidos un buen rato. Tiempo estimado de creación: 10 minutos (más el tiempo de congelación).', 'The elf has brought a piece of the North Pole! He has hidden several chocolate coins inside a block of ice left in the kitchen sink. Beside it, there is a small note with instructions on how the kids must use "tools" (warm water and salt) to rescue the trapped loot.' || char(10) || char(10) || 'Materials: a container of water previously frozen with coins or toys inside, and a tray to catch any drips. It is an incredible sensory activity that will keep the kids entertained for a good while. Estimated creation time: 10 minutes (plus freezing time).', 'elf_treasure', '[{"label":"TREASURE"},{"label":"SNOW"},{"label":"MEDIUM"}]', 0),
(137, 'Patinaje sobre Cristal', 'Ice Crystal Skating', 'El elfo ha convertido la mesa del comedor en una pista de patinaje sobre hielo olímpica. Usando un espejo o papel de aluminio estirado, se encuentra haciendo piruetas sobre sus patines hechos de clips, rodeado de otros juguetes que hacen de público entusiasmado por su actuación.' || char(10) || char(10) || 'Necesitarás papel de aluminio o un espejo plano, dos clips metálicos para los pies del elfo y un poco de bicarbonato de sodio para simular la nieve acumulada en los bordes de la pista. Tiempo estimado de creación: 10 minutos.', 'The elf has turned the dining room table into an Olympic ice skating rink. Using a mirror or stretched aluminum foil, he is spinning on skates made of paper clips, surrounded by other toys acting as an enthusiastic audience cheering his performance.' || char(10) || char(10) || 'You will need aluminum foil or a flat mirror, two metal paper clips for the elf''s feet, and a little baking soda to simulate snow piled up around the edges of the rink. Estimated creation time: 10 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(4, 'Cuidado con la Tostadora', 'Watch Out for the Toaster', '¡Situación de peligro en la cocina! El elfo ha intentado ver cómo funciona la tostadora y se ha quedado medio asomado por una de las ranuras. Parece que buscaba el calor del hogar, pero ha terminado rodeado de migas de pan y con cara de no saber muy bien cómo salir de ese laberinto de metal.' || char(10) || char(10) || 'Solo necesitas una tostadora (¡desenchufada siempre!) y un par de rebanadas de pan tostado real para decorar la escena. Coloca al elfo de modo que solo asome la mitad superior del cuerpo. Tiempo estimado de creación: 5 minutos.', 'Danger in the kitchen! The elf tried to figure out how the toaster works and ended up half-stuck in one of the slots. It seems he was looking for warmth but has ended up surrounded by breadcrumbs with no idea how to escape this metal maze.' || char(10) || char(10) || 'All you need is a toaster (always unplugged!) and a couple of real toast slices to decorate the scene. Place the elf so that only the upper half of his body sticks out. Estimated creation time: 5 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(54, 'El Desfile de Moda del Armario', 'The Wardrobe Fashion Show', 'El elfo ha decidido que su traje rojo es demasiado aburrido y ha asaltado el cajón de los calcetines. Se ha fabricado un "vestido de alta costura" uniendo varios calcetines desparejados con pinzas de la ropa y está desfilando sobre una pasarela hecha de zapatos alineados.' || char(10) || char(10) || 'Busca 4 o 5 calcetines de colores brillantes, pinzas de la ropa pequeñas y los zapatos más divertidos de la familia para crear la pasarela. Es una escena muy colorida y simpática para el dormitorio. Tiempo estimado de creación: 15 minutos.', 'The elf decided his red suit was too boring and raided the sock drawer. He has made a "haute couture gown" by joining mismatched socks with clothespins and is strutting down a runway made of lined-up shoes.' || char(10) || char(10) || 'Find 4 or 5 brightly colored socks, small clothespins, and the family''s most fun shoes to create the runway. It is a very colorful and charming scene for the bedroom. Estimated creation time: 15 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"BEDROOM"},{"label":"MEDIUM"}]', 0),
(128, 'El Árbol de Construcción Galáctica', 'The Galactic Construction Tree', '¡Trabajo en equipo! El elfo ha traído sus piezas de construcción favoritas y está ayudando a montar un árbol de Navidad alternativo hecho completamente de bloques. Se le ve con un casco de obra (hecho de papel) dirigiendo a otras figuras de acción en esta gran obra de ingeniería.' || char(10) || char(10) || 'Materiales: Bloques de construcción tipo LEGO o similares, cartulina amarilla para el casco y un plano dibujado a mano sobre un trozo de papel. Puedes construir una estructura simple y dejar que el elfo sostenga la última pieza. Tiempo estimado de creación: 25 minutos.', 'Teamwork! The elf has brought his favorite building pieces and is helping to assemble an alternative Christmas tree made entirely of blocks. He can be seen wearing a hard hat (made of paper) and directing action figures in this great engineering project.' || char(10) || char(10) || 'Materials: LEGO or similar building blocks, yellow cardstock for the hard hat, and a hand-drawn blueprint on a piece of paper. You can build a simple structure and let the elf hold the last piece. Estimated creation time: 25 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"ADVENTURE"},{"label":"HARD"}]', 0),
(93, 'Poción Mágica en el Lavabo', 'Magic Potion in the Sink', 'Un experimento alquímico ha tenido lugar en el cuarto de baño. El elfo ha mezclado "polvos de estrellas" en el agua del lavabo y la ha vuelto de un color verde fluorescente. Está sosteniendo un cepillo de dientes como si fuera una varita mágica, sorprendido por el resultado de su propio hechizo.' || char(10) || char(10) || 'Para este efecto necesitarás colorante alimentario (solo unas gotas en el agua del lavabo taponado) y un poco de purpurina biodegradable. Es una sorpresa visual muy potente cuando los niños entran a lavarse los dientes. Tiempo estimado de creación: 5 minutos.', 'An alchemical experiment has taken place in the bathroom. The elf has mixed "star dust" into the sink water and turned it a fluorescent green. He is holding a toothbrush as if it were a magic wand, surprised by the result of his own spell.' || char(10) || char(10) || 'For this effect you will need food coloring (just a few drops in the plugged sink water) and a little biodegradable glitter. It is a very powerful visual surprise when the kids come in to brush their teeth. Estimated creation time: 5 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"BATHROOM"},{"label":"MEDIUM"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(61, 'Jacuzzi de Chocolate Caliente', 'Hot Chocolate Jacuzzi', 'Después de una noche gélida vigilando la casa, el elfo ha decidido entrar en calor con un baño de lujo. Ha llenado una de las tazas favoritas de la familia con cacao en polvo y ha creado un jacuzzi de chocolate donde descansa plácidamente, rodeado de una densa capa de mini nubes que actúan como burbujas relajantes.' || char(10) || char(10) || 'Para esta escena necesitarás una taza de café, chocolate en polvo (solo para la superficie si no quieres gastar mucho), mini malvaviscos y una pajita de papel decorativa. Coloca al elfo con los brazos hacia fuera para que parezca que disfruta del vapor. Tiempo estimado de creación: 5 minutos.', 'After a freezing night watching over the house, the elf has decided to warm up with a luxury bath. He has filled one of the family''s favorite mugs with cocoa powder and created a chocolate jacuzzi where he rests peacefully, surrounded by a thick layer of mini marshmallows acting as relaxing bubbles.' || char(10) || char(10) || 'For this scene you will need a coffee mug, cocoa powder (just for the surface if you don''t want to use much), mini marshmallows, and a decorative paper straw. Place the elf with his arms out to make it look like he is enjoying the steam. Estimated creation time: 5 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(68, 'El Camino del Arcoíris de Cereales', 'The Rainbow Cereal Path', '¡La cocina se ha vuelto mágica! El elfo ha decidido que el camino hacia el desayuno debe ser especial y ha creado un sendero multicolor que atraviesa toda la encimera. Al final del arcoíris, el elfo espera sentado sobre una montaña de cereales, asegurándose de que nadie se quede sin su dosis de energía matutina.' || char(10) || char(10) || 'Materiales necesarios: Una caja de cereales redondos de colores (tipo Froot Loops), un par de nubes blancas para simular las nubes al principio y final del camino, y un poco de algodón. Ordena los cereales por colores para crear el efecto degradado. Tiempo estimado de creación: 15 minutos.', 'The kitchen has turned magical! The elf has decided that the path to breakfast should be special and created a multicolor trail across the entire counter. At the end of the rainbow, the elf sits waiting on a mountain of cereal, making sure no one misses their morning energy boost.' || char(10) || char(10) || 'Materials needed: a box of round colored cereals (like Froot Loops), a couple of white marshmallows to simulate clouds at the start and end of the path, and a bit of cotton. Sort the cereals by color to create the gradient effect. Estimated creation time: 15 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(43, 'Pizzería Artesanal del Elfo', 'The Elf''s Artisan Pizzeria', '¡Hoy no se cocina, el elfo se encarga! Ha montado su propio puesto de pizzas minúsculas sobre la mesa. Con un delantal improvisado y las manos manchadas de "harina", el elfo presenta sus creaciones artesanales del tamaño de un bocado, listas para ser devoradas por cualquier juguete hambriento que pase por allí.' || char(10) || char(10) || 'Necesitarás galletas saladas redondas para la base, un poco de mermelada roja o ketchup para la salsa, y queso rallado real o coco seco. Como toque final, usa un trozo de caja de cartón pequeña para simular el embalaje de la pizza. Tiempo estimado de creación: 20 minutos.', 'No cooking today — the elf is in charge! He has set up his own mini pizza stand on the table. With an improvised apron and "flour"-stained hands, the elf presents his bite-sized artisan creations, ready to be devoured by any hungry toy passing by.' || char(10) || char(10) || 'You will need round crackers for the base, a bit of red jam or ketchup for the sauce, and real grated cheese or shredded coconut. As a final touch, use a small piece of cardboard box to simulate pizza packaging. Estimated creation time: 20 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(147, 'Buceo en el Mar de Gelatina', 'Diving in the Jelly Sea', 'El elfo ha encontrado un océano azul y dulce en la nevera. Equipado con un visor de buceo, se ha sumergido en un cuenco de gelatina donde intenta atrapar unos peces de gominola que han quedado atrapados en la profundidad. Es una escena visualmente impactante y muy refrescante para los niños.' || char(10) || char(10) || 'Materiales: Un paquete de gelatina azul preparado el día anterior, pececitos de gominola introducidos antes de que cuaje y una pajita cortada para simular el tubo de buceo. Recuerda limpiar bien al elfo después de esta aventura para que no se quede pegajoso. Tiempo estimado de creación: 10 minutos (más preparación de la gelatina).', 'The elf has found a sweet blue ocean in the fridge. Equipped with a diving mask, he has submerged himself in a bowl of jelly where he tries to catch gummy fish trapped in the depths. It is a visually striking and very refreshing scene for the kids.' || char(10) || char(10) || 'Materials: a packet of blue jelly prepared the day before, gummy fish inserted before it sets, and a cut straw to simulate the diving tube. Remember to clean the elf well after this adventure so he doesn''t stay sticky. Estimated creation time: 10 minutes (plus jelly preparation time).', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"HARD"}]', 0),
(138, 'Cárcel de Bastones de Caramelo', 'Candy Cane Prison', '¡Atrapado por su glotonería! El elfo intentó llevarse todos los bastones de caramelo del árbol y ha terminado encerrado en una prisión de azúcar. Los bastones forman los barrotes de su celda y tiene un cartel que dice "Perdón por ser tan dulce", mientras mira con arrepentimiento a través de las rayas rojas y blancas.' || char(10) || char(10) || 'Necesitarás entre 8 y 10 bastones de caramelo reales y un poco de cinta adhesiva o cordel para unirlos en la parte superior e inferior formando una jaula. Coloca al elfo dentro antes de cerrar la estructura. Tiempo estimado de creación: 15 minutos.', 'Trapped by his own gluttony! The elf tried to take all the candy canes from the tree and ended up locked in a sugar prison. The candy canes form the bars of his cell and he has a sign reading "Sorry for being so sweet", looking remorsefully through the red and white stripes.' || char(10) || char(10) || 'You will need between 8 and 10 real candy canes and a bit of adhesive tape or string to join them at the top and bottom to form a cage. Place the elf inside before closing the structure. Estimated creation time: 15 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"DANGER"},{"label":"EASY"}]', 0),
(111, 'La Pastelería de Mini Donas', 'The Mini Donut Bakery', 'El elfo ha decidido que las donas normales son demasiado grandes para él, así que ha horneado su propia tanda de "mini donas" navideñas. Las tiene expuestas en un plato pequeño, decoradas con glaseado y chispitas de colores, invitando a todos a probar estas delicias del tamaño de una uña.' || char(10) || char(10) || 'Para esta manualidad usa cereales redondos con agujero (tipo Cheerios o Anisados), sumérgelos en chocolate derretido o glaseado de azúcar y añade virutas de colores mientras estén húmedos. Es un detalle comestible que encanta a los más pequeños. Tiempo estimado de creación: 15 minutos.', 'The elf decided that regular donuts are too big for him, so he has baked his own batch of Christmas "mini donuts". They are displayed on a small plate, decorated with icing and colorful sprinkles, inviting everyone to try these fingernail-sized treats.' || char(10) || char(10) || 'For this craft use ring-shaped cereals (like Cheerios or similar), dip them in melted chocolate or sugar icing, and add colorful sprinkles while still wet. It is an edible detail that the little ones will love. Estimated creation time: 15 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(119, 'Aventura en la Selva de Brócoli', 'Adventure in the Broccoli Jungle', 'Incluso los elfos saben que hay que comer verdura, ¡aunque sea para jugar! El elfo se ha perdido en un bosque de árboles gigantes verdes (ramilletes de brócoli) y está intentando encontrar el camino de salida. Ha montado un picnic saludable en un claro del bosque usando una rodaja de zanahoria como mesa.' || char(10) || char(10) || 'Materiales: 3 o 4 piezas grandes de brócoli crudo, una rodaja de zanahoria y un poco de hummus o salsa ranchera para simular un "charco" de barro. Es una forma divertida de presentar vegetales a los niños. Tiempo estimado de creación: 10 minutos.', 'Even elves know you have to eat your vegetables — even if just for play! The elf has gotten lost in a forest of giant green trees (broccoli florets) and is trying to find his way out. He has set up a healthy picnic in a clearing using a carrot slice as a table.' || char(10) || char(10) || 'Materials: 3 or 4 large pieces of raw broccoli, a carrot slice, and a little hummus or ranch dressing to simulate a "mud puddle". It is a fun way to introduce vegetables to the kids. Estimated creation time: 10 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(87, 'Piscina de Virutas Mágicas', 'Magic Sprinkles Pool', '¡Se acabó el frío, es hora de nadar! El elfo ha convertido un bol de cristal en una piscina de bolas, pero en lugar de plástico, ha usado miles de virutas de colores dulces. Está tumbado boca arriba con unas gafas de sol hechas de papel, disfrutando de un "baño" extremadamente azucarado y colorido.' || char(10) || char(10) || 'Necesitarás un cuenco pequeño y un par de botes de virutas (sprinkles) de colores para tartas. Si no tienes suficientes virutas, puedes rellenar el fondo con arroz y poner las virutas solo en la capa superior. Tiempo estimado de creación: 5 minutos.', 'No more cold — time to swim! The elf has turned a glass bowl into a ball pit, but instead of plastic, he has used thousands of sweet colorful sprinkles. He is lying on his back wearing paper sunglasses, enjoying an extremely sugary and colorful "bath".' || char(10) || char(10) || 'You will need a small bowl and a couple of jars of colorful cake sprinkles. If you don''t have enough sprinkles, you can fill the bottom with rice and put the sprinkles only on the top layer. Estimated creation time: 5 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(117, 'La Fortaleza de Azúcar', 'The Sugar Fortress', 'El elfo ha construido una defensa impenetrable en la cocina. Usando bloques de ingeniería comestibles (terrones de azúcar), ha levantado una muralla fortificada desde donde vigila que nadie robe los dulces de Navidad antes de tiempo. Es una obra de arquitectura dulce que desafía la gravedad.' || char(10) || char(10) || 'Materiales: Una caja de terrones de azúcar y un poco de miel o leche condensada para usar como pegamento entre los bloques. Puedes añadir pequeñas banderas hechas con palillos y papel. Tiempo estimado de creación: 30 minutos.', 'The elf has built an impenetrable defense in the kitchen. Using edible engineering blocks (sugar cubes), he has erected a fortified wall from which he keeps watch to make sure no one steals the Christmas sweets before it is time. It is a sweet architectural achievement that defies gravity.' || char(10) || char(10) || 'Materials: a box of sugar cubes and a little honey or condensed milk to use as glue between the blocks. You can add small flags made with toothpicks and paper. Estimated creation time: 30 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"HARD"}]', 0),
(67, 'El Barista de Batidos', 'The Smoothie Barista', '¡Marchando un batido especial! El elfo ha tomado el control de la batidora y ha preparado una bebida mágica. Está sosteniendo una pajita gigante que se introduce en un vaso de leche con chocolate, con una montaña de nata montada que le llega hasta el gorro y virutas de chocolate por todas partes.' || char(10) || char(10) || 'Prepara un vaso de leche con cacao, añade nata montada real (o algodón si prefieres que dure todo el día) y coloca al elfo sujetando una pajita dentro del vaso. Ten cuidado de no manchar demasiado el traje del elfo. Tiempo estimado de creación: 10 minutos.', 'One special smoothie coming right up! The elf has taken over the blender and prepared a magic drink. He is holding a giant straw dipped into a glass of chocolate milk, with a mountain of whipped cream reaching all the way up to his hat and chocolate sprinkles everywhere.' || char(10) || char(10) || 'Prepare a glass of cocoa milk, add real whipped cream (or cotton if you prefer it to last all day), and place the elf holding a straw inside the glass. Be careful not to stain the elf''s suit too much. Estimated creation time: 10 minutes.', 'elf_food', '[{"label":"FOOD"},{"label":"KITCHEN"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(82, 'La Pasarela de Alta Costura', 'The High Fashion Runway', '¡El pasillo se ha convertido en la Fashion Week! El elfo ha desplegado una bufanda larga a modo de alfombra roja y ha desfilado con un "traje" hecho con un envoltorio de bombón brillante. Está rodeado de otros peluches que hacen de fotógrafos con cámaras de juguete, capturando su mejor ángulo.' || char(10) || char(10) || 'Para esta manualidad necesitarás una bufanda colorida, un poco de papel de aluminio o envoltorios de dulces para su ropa, y otros juguetes de la casa. Coloca al elfo en una pose de modelo profesional. Tiempo estimado de creación: 15 minutos.', 'The hallway has become Fashion Week! The elf has rolled out a long scarf as a red carpet and is strutting in an "outfit" made from a shiny candy wrapper. He is surrounded by stuffed animals acting as photographers with toy cameras, capturing his best angle.' || char(10) || char(10) || 'For this craft you will need a colorful scarf, some aluminum foil or candy wrappers for his clothes, and other toys from around the house. Place the elf in a professional model pose. Estimated creation time: 15 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"FESTIVAL"},{"label":"MEDIUM"}]', 0),
(102, 'Atrapado en el Calcetín Perdido', 'Trapped in the Lost Sock', 'Parece que el elfo intentó buscar ese calcetín que siempre desaparece en la lavadora y ha terminado metido en un lío. Solo se le ven las piernas asomando por la parte superior de un calcetín desparejado, mientras el resto de su cuerpo está totalmente oculto en las profundidades del tejido.' || char(10) || char(10) || 'Materiales: Un calcetín de adulto (preferiblemente con motivos navideños) y un poco de relleno o papel en el fondo para que el calcetín mantenga la forma mientras el elfo está dentro boca abajo. Tiempo estimado de creación: 5 minutos.', 'It seems the elf tried to find that sock that always disappears in the washing machine and ended up in quite a mess. Only his legs are visible poking out of the top of a mismatched sock, while the rest of his body is completely hidden in the depths of the fabric.' || char(10) || char(10) || 'Materials: an adult sock (preferably with Christmas patterns) and a little stuffing or paper at the bottom to keep the sock''s shape while the elf is inside upside-down. Estimated creation time: 5 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"DANGER"},{"label":"EASY"}]', 0),
(92, 'El Columpio de Percha', 'Hanger Swing', '¡Adrenalina en el armario! El elfo ha encontrado una percha libre y la ha convertido en un columpio trapecista. Está colgado de la barra del armario o de un pomo de una puerta, balanceándose con alegría mientras observa toda la ropa desde una perspectiva muy divertida.' || char(10) || char(10) || 'Necesitarás una percha de ropa normal y un poco de hilo de pescar o cordel para asegurar las manos del elfo a la barra inferior de la percha. Asegúrate de que quede bien equilibrado para que no se caiga. Tiempo estimado de creación: 10 minutos.', 'Adrenaline in the wardrobe! The elf has found a free hanger and turned it into a trapeze swing. He is hanging from the wardrobe rail or a door handle, swinging happily while enjoying a very fun view of all the clothes.' || char(10) || char(10) || 'You will need a regular clothes hanger and a bit of fishing line or string to secure the elf''s hands to the bottom bar of the hanger. Make sure he is well balanced so he doesn''t fall. Estimated creation time: 10 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(17, 'Expedición al Monte Zapato', 'Expedition to Mount Shoe', 'Para un elfo, un montón de zapatos es una cordillera esperando ser explorada. Se encuentra en la cima del zapato más alto de la casa, equipado con una "mochila" (un tapón de botella con tiras de hilo) y una bandera de victoria que ha clavado en la lengüeta del calzado.' || char(10) || char(10) || 'Materiales: Varios zapatos y botas de la familia apilados artísticamente, un palillo de dientes y un trozo de papel para la bandera. Es una escena ideal para dejar en el recibidor o la entrada. Tiempo estimado de creación: 10 minutos.', 'For an elf, a pile of shoes is a mountain range waiting to be explored. He is standing on top of the tallest shoe in the house, equipped with a "backpack" (a bottle cap with yarn straps) and a victory flag planted in the tongue of the shoe.' || char(10) || char(10) || 'Materials: several shoes and boots from the family artistically stacked, a toothpick, and a piece of paper for the flag. It is a great scene to leave in the hallway or entryway. Estimated creation time: 10 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(105, 'Saco de Dormir de Guante', 'Glove Sleeping Bag', 'Incluso los ayudantes de Santa necesitan una siesta acogedora. El elfo ha encontrado un guante de lana y se ha metido dentro como si fuera un saco de dormir térmico. Solo asoma su carita y su gorro rojo, descansando plácidamente sobre un cojín del sofá o en la mesita de noche.' || char(10) || char(10) || 'Solo necesitas un guante o una manopla de invierno. Puedes doblar el borde del guante hacia fuera para que parezca una cama de verdad y colocar un pañuelo pequeño a modo de almohada. Tiempo estimado de creación: 5 minutos.', 'Even Santa''s helpers need a cozy nap. The elf has found a wool glove and crawled inside as if it were a thermal sleeping bag. Only his little face and red hat are peeking out, resting peacefully on a sofa cushion or bedside table.' || char(10) || char(10) || 'All you need is a winter glove or mitten. You can fold the edge of the glove outward to make it look like a real bed and place a small handkerchief as a pillow. Estimated creation time: 5 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(89, 'El Túnel del Pantalón', 'The Trouser Tunnel', '¡Misión de exploración subterránea! El elfo ha decidido que las perneras de unos vaqueros son túneles secretos que conectan las habitaciones. Se le puede ver asomando la cabeza por el tobillo de un pantalón que se ha quedado "olvidado" sobre la cama, con una linterna en la mano.' || char(10) || char(10) || 'Materiales: Unos pantalones vaqueros o de chándal y una linterna pequeña (puede ser de juguete o una luz LED). Coloca los pantalones con un poco de volumen para que parezca que hay alguien moviéndose dentro. Tiempo estimado de creación: 8 minutos.', 'Underground exploration mission! The elf has decided that the legs of a pair of jeans are secret tunnels connecting the rooms. He can be seen poking his head out of the ankle of a pair of trousers left "forgotten" on the bed, flashlight in hand.' || char(10) || char(10) || 'Materials: a pair of jeans or sweatpants and a small flashlight (a toy one or an LED light). Add some volume to the trousers to make it look like someone is moving inside. Estimated creation time: 8 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"MYSTERY"},{"label":"EASY"}]', 0),
(50, 'Encantador de Corbatas', 'Tie Snake Charmer', 'En un rincón del salón, el elfo se ha convertido en un encantador de serpientes, pero en lugar de cobras, está usando las corbatas de papá. Sentado con las piernas cruzadas y una flauta (un lápiz), ha logrado que las corbatas "bailen" y se mantengan erguidas frente a él.' || char(10) || char(10) || 'Necesitarás 2 o 3 corbatas y un poco de alambre fino por dentro de las mismas para que mantengan la forma vertical. Usa un lápiz o un palito como flauta para el elfo. Tiempo estimado de creación: 20 minutos.', 'In a corner of the living room, the elf has become a snake charmer — but instead of cobras, he is using dad''s neckties. Sitting cross-legged with a flute (a pencil), he has made the ties "dance" and stand upright before him.' || char(10) || char(10) || 'You will need 2 or 3 neckties and a little thin wire threaded inside them to hold the vertical shape. Use a pencil or a small stick as the elf''s flute. Estimated creation time: 20 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(146, 'Escondite en el Gorro de Lana', 'Hiding in the Wool Hat', '¡Cuidado al ponerte el gorro hoy! El elfo se ha camuflado perfectamente dentro de un gorro de lana con pompón. Ha dado la vuelta al gorro y lo ha convertido en un nido circular donde se ha hecho un ovillo, casi imposible de detectar a primera vista si no te fijas en su gorrito rojo.' || char(10) || char(10) || 'Solo necesitas un gorro de lana de invierno. Dale la vuelta o hazle un hueco en el centro y coloca al elfo de forma que quede bien resguardado y calentito. Tiempo estimado de creación: 5 minutos.', 'Watch out when you put on your hat today! The elf has perfectly camouflaged himself inside a pom-pom wool beanie. He has turned the hat over and made it into a circular nest where he has curled up, almost impossible to spot at first glance if you don''t notice his little red hat.' || char(10) || char(10) || 'All you need is a winter wool hat. Turn it inside out or make a hollow in the center and place the elf so he is snug and warm inside. Estimated creation time: 5 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(99, 'El Duende de Lavandería', 'The Laundry Gnome', 'Nuestro amigo ha decidido que es un buen día para hacer la colada, pero se ha pasado con el detergente. Está sentado encima de la lavadora rodeado de una montaña de "espuma" blanca (bolas de algodón) y sostiene un calcetín diminuto que parece haber encogido en el lavado.' || char(10) || char(10) || 'Materiales: Bolas de algodón, un bote de detergente vacío y un calcetín de bebé o una prenda muy pequeña. Esparce el algodón para simular que la espuma se está desbordando. Tiempo estimado de creación: 12 minutos.', 'Our friend has decided it is a good day to do laundry, but went way overboard with the detergent. He is sitting on top of the washing machine surrounded by a mountain of white "foam" (cotton balls) and is holding a tiny sock that seems to have shrunk in the wash.' || char(10) || char(10) || 'Materials: cotton balls, an empty detergent bottle, and a baby sock or a very small garment. Spread the cotton around to simulate overflowing foam. Estimated creation time: 12 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"BATHROOM"},{"label":"MEDIUM"}]', 0),
(65, 'Bufanda-Serpiente en el Pasillo', 'Scarf-Snake in the Hallway', '¡Cuidado por dónde pisas! El elfo ha domado una bufanda de rayas y la ha colocado en forma de zigzag por el pasillo para que parezca una serpiente gigante. Él va montado sobre la "cabeza" de la serpiente, usando un cinturón a modo de riendas para dirigir a su nueva y suave mascota.' || char(10) || char(10) || 'Necesitarás una bufanda larga, un cinturón fino o un cordón de zapato para las riendas, y un par de botones o pegatinas para ponerle ojos a la bufanda. Tiempo estimado de creación: 10 minutos.', 'Watch where you step! The elf has tamed a striped scarf and arranged it in a zigzag across the hallway to look like a giant snake. He is riding on the "head" of the snake, using a belt as reins to steer his new soft pet.' || char(10) || char(10) || 'You will need a long scarf, a thin belt or shoelace for the reins, and a couple of buttons or stickers to give the scarf some eyes. Estimated creation time: 10 minutes.', 'elf_clothes', '[{"label":"CLOTHES"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(123, 'Salto Base desde la Lámpara', 'Base Jump from the Lamp', '¡El elfo se ha lanzado al vacío! Aprovechando la altura de la lámpara del salón, ha improvisado un paracaídas circular y está descendiendo lentamente hacia el sofá. Es una maniobra arriesgada que solo un elfo entrenado en el Polo Norte podría ejecutar con tanta elegancia.' || char(10) || char(10) || 'Materiales: Una servilleta de papel grande o un filtro de café, cuatro hilos de lana y cinta adhesiva para unir los hilos a la espalda del elfo. Cuélgalo del techo o la lámpara con un hilo de pescar invisible para que parezca que está flotando en el aire. Tiempo estimado de creación: 15 minutos.', 'The elf has leapt into the void! Taking advantage of the height of the living room lamp, he has improvised a circular parachute and is slowly descending toward the sofa. It is a daring maneuver that only a North Pole-trained elf could execute with such elegance.' || char(10) || char(10) || 'Materials: a large paper napkin or coffee filter, four yarn strings, and adhesive tape to attach the strings to the elf''s back. Hang him from the ceiling or lamp with invisible fishing line to make it look like he is floating in mid-air. Estimated creation time: 15 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(97, 'Rápel por la Nevera Ártica', 'Rappelling Down the Arctic Fridge', 'La conquista de la cocina ha comenzado. El elfo ha sido avistado descendiendo por la puerta de la nevera mediante una cuerda de seguridad profesional. Su objetivo parece ser el cajón de los embutidos, y no se detendrá ante nada hasta completar su misión de descenso vertical.' || char(10) || char(10) || 'Necesitarás un cordel largo o hilo dental y un clip de oficina que sirva como mosquetón de escalada. Fija un extremo de la cuerda a la parte superior de la nevera con un imán o cinta, y enrolla el otro extremo en el cuerpo del elfo en una pose de descenso. Tiempo estimado de creación: 10 minutos.', 'The kitchen conquest has begun. The elf has been spotted descending the fridge door using a professional safety rope. His target appears to be the cold cuts drawer, and he will stop at nothing to complete his vertical descent mission.' || char(10) || char(10) || 'You will need a long string or dental floss and an office clip serving as a climbing carabiner. Fix one end of the rope to the top of the fridge with a magnet or tape, and wrap the other end around the elf''s body in a rappelling pose. Estimated creation time: 10 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(77, 'Safari entre Dinosaurios', 'Safari Among Dinosaurs', '¡Supervivencia en la era jurásica! El elfo ha viajado en el tiempo y ha sido capturado cabalgando sobre el lomo de un temible T-Rex. Armado con un lazo de cuerda, está intentando domar a las bestias prehistóricas del cuarto de juegos en una expedición de safari sin precedentes.' || char(10) || char(10) || 'Materiales: Figuras de dinosaurios de juguete o animales de plástico grandes y un trozo de cordel para simular las riendas. Coloca al elfo sentado firmemente sobre el juguete más grande que encuentres para darle escala a la aventura. Tiempo estimado de creación: 10 minutos.', 'Survival in the Jurassic era! The elf has traveled through time and been caught riding on the back of a fearsome T-Rex. Armed with a rope lasso, he is trying to tame the prehistoric creatures of the playroom in an unprecedented safari expedition.' || char(10) || char(10) || 'Materials: toy dinosaur figures or large plastic animals and a piece of string to simulate the reins. Place the elf firmly seated on the largest toy you can find to give the adventure a sense of scale. Estimated creation time: 10 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(37, 'Rafting en los Rápidos del Baño', 'Bathroom Rapids Rafting', 'El elfo ha construido una balsa de salvamento y se está enfrentando a las embravecidas aguas del lavabo. Con un remo en la mano y una actitud desafiante, navega entre burbujas de jabón buscando la orilla de la encimera en esta peligrosa travesía fluvial.' || char(10) || char(10) || 'Necesitarás un par de esponjas de cocina unidas o unos palitos de helado para formar la balsa, y un bastoncillo de los oídos como remo. Puedes añadir un poco de papel de seda azul alrededor para simular las olas del río. Tiempo estimado de creación: 15 minutos.', 'The elf has built a life raft and is tackling the rough waters of the sink. With an oar in hand and a defiant attitude, he navigates through soap bubbles looking for the shore of the countertop on this dangerous river crossing.' || char(10) || char(10) || 'You will need a couple of kitchen sponges joined together or popsicle sticks to form the raft, and a cotton swab as an oar. You can add blue tissue paper around it to simulate river waves. Estimated creation time: 15 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"BATHROOM"},{"label":"MEDIUM"}]', 0),
(116, 'Exploración de la Cueva de Cojines', 'Exploring the Cushion Cave', 'En las profundidades del sofá existe un mundo desconocido. El elfo se ha equipado con una linterna frontal y se ha adentrado en una oscura gruta formada por los cojines. Su misión es recuperar el "mando a distancia perdido", una reliquia antigua que los humanos buscan desesperadamente.' || char(10) || char(10) || 'Materiales: Los cojines del sofá dispuestos en forma de túnel y una luz LED pequeña o una linterna de juguete. Coloca al elfo asomando la cabeza desde la oscuridad del túnel para generar misterio. Tiempo estimado de creación: 10 minutos.', 'Deep within the sofa there exists an unknown world. The elf has equipped himself with a headlamp and ventured into a dark grotto formed by the cushions. His mission is to recover the "lost remote control", an ancient relic that humans desperately search for.' || char(10) || char(10) || 'Materials: sofa cushions arranged in a tunnel shape and a small LED light or toy flashlight. Place the elf poking his head out from the darkness of the tunnel to create mystery. Estimated creation time: 10 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(5, 'Vuelo Acrobático en Avión de Papel', 'Acrobatic Flight in a Paper Plane', '¡Cuidado con el tráfico aéreo! El elfo ha diseñado un prototipo de avión de papel de alta velocidad y está sobrevolando el pasillo. Parece que ha perdido el control y está a punto de realizar un aterrizaje forzoso sobre la planta del recibidor.' || char(10) || char(10) || 'Solo necesitas una hoja de papel para hacer el avión (puedes buscar un diseño complejo tipo "stunt") y un poco de cinta para asegurar al elfo en la "cabina". Cuélgalo del techo con hilo invisible para que parezca que está en pleno vuelo. Tiempo estimado de creación: 10 minutos.', 'Watch out for air traffic! The elf has designed a high-speed paper plane prototype and is soaring through the hallway. It looks like he has lost control and is about to make a forced landing on the entryway plant.' || char(10) || char(10) || 'All you need is a sheet of paper to fold the plane (you can look up a complex "stunt" design) and a bit of tape to secure the elf in the "cockpit". Hang it from the ceiling with invisible thread to make it look like it is in mid-flight. Estimated creation time: 10 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(18, 'Cruce del Puente Colgante', 'Crossing the Suspension Bridge', 'El abismo entre la mesa y la silla es enorme, pero el elfo ha construido un puente de ingeniería con materiales de fortuna. Se encuentra justo en el centro del puente, manteniendo el equilibrio mientras el viento (del ventilador) amenaza con hacerlo caer al vacío del suelo de madera.' || char(10) || char(10) || 'Materiales: Dos sillas o muebles cercanos, varios lápices o reglas de plástico para los tablones y cordel para las barandillas del puente. Es una construcción que requiere algo de equilibrio y paciencia. Tiempo estimado de creación: 25 minutos.', 'The gap between the table and the chair is enormous, but the elf has built an engineering bridge from makeshift materials. He is right in the center of the bridge, keeping his balance while the wind (from the fan) threatens to knock him into the wooden floor below.' || char(10) || char(10) || 'Materials: two chairs or nearby furniture, several pencils or plastic rulers for the planks, and string for the bridge railings. It is a build that requires some balance and patience. Estimated creation time: 25 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"HARD"}]', 0),
(26, 'Misión Espacial: Aterrizaje Lunar', 'Space Mission: Lunar Landing', '¡Un pequeño paso para un elfo, un gran salto para la Navidad! Nuestro aventurero ha aterrizado su nave espacial en un planeta desconocido (una calabaza o un balón de fútbol). Ha plantado su bandera y está recogiendo muestras de rocas lunares para llevarlas de vuelta al Polo Norte.' || char(10) || char(10) || 'Necesitarás papel de aluminio para envolver un objeto redondo, un palillo de dientes con un trozo de papel para la bandera y un casco improvisado con un vaso de plástico transparente pequeño. Tiempo estimado de creación: 20 minutos.', 'One small step for an elf, one giant leap for Christmas! Our adventurer has landed his spaceship on an unknown planet (a pumpkin or a soccer ball). He has planted his flag and is collecting lunar rock samples to bring back to the North Pole.' || char(10) || char(10) || 'You will need aluminum foil to wrap a round object, a toothpick with a piece of paper for the flag, and an improvised helmet made from a small transparent plastic cup. Estimated creation time: 20 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"BEDROOM"},{"label":"HARD"}]', 0),
(70, 'Carrera de Obstáculos Ninja', 'Ninja Obstacle Course', 'El entrenamiento para repartir regalos es duro. El elfo ha montado un circuito de entrenamiento ninja en el suelo del salón: debe saltar sobre bloques de construcción, reptar bajo hilos de lana y escalar muros de libros sin ser detectado por los radares enemigos.' || char(10) || char(10) || 'Materiales: Piezas de LEGO, hilos de colores estirados entre muebles bajos y libros apilados. Coloca al elfo en una postura de sigilo, como si estuviera a punto de saltar un obstáculo. Tiempo estimado de creación: 20 minutos.', 'Training to deliver gifts is tough. The elf has set up a ninja training circuit on the living room floor: he must jump over building blocks, crawl under yarn strings, and scale walls of books without being detected by enemy radar.' || char(10) || char(10) || 'Materials: LEGO pieces, colored strings stretched between low furniture, and stacked books. Place the elf in a stealth pose, as if about to leap over an obstacle. Estimated creation time: 20 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(52, 'Infiltración en la Fortaleza de Regalos', 'Infiltrating the Gift Fortress', 'El elfo ha sido enviado en una misión de reconocimiento para verificar el estado de los paquetes. Ha usado ventosas (celo doblado) para trepar por las cajas de cartón y está espiando por una pequeña rendija del papel de regalo para confirmar el contenido secreto.' || char(10) || char(10) || 'Necesitarás algunas cajas vacías envueltas en papel de regalo y un cúter para hacer un corte pequeño por donde asome el elfo. Es una escena que genera muchísima expectación en los niños. Tiempo estimado de creación: 15 minutos.', 'The elf has been sent on a reconnaissance mission to check on the packages. He used suction cups (folded tape) to climb the cardboard boxes and is peeking through a small gap in the wrapping paper to confirm the secret contents.' || char(10) || char(10) || 'You will need a few empty boxes wrapped in gift paper and a cutter to make a small slit for the elf to poke through. It is a scene that builds huge excitement in the kids. Estimated creation time: 15 minutes.', 'elf_adventure', '[{"label":"ADVENTURE"},{"label":"TREASURE"},{"label":"MEDIUM"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(3, 'El Escritor de Postales Navideñas', 'The Christmas Postcard Writer', 'Nuestro elfo sabe que no hay nada más bonito que una felicitación escrita a mano. Se ha pasado la noche redactando mini postales para todos los juguetes de la casa y para la familia, usando un buzón improvisado para que los niños dejen sus propias cartas a Santa.' || char(10) || char(10) || 'Necesitarás cartulina de colores cortada en rectángulos diminutos, sobres de papel hechos a mano y un bolígrafo de punta fina. Puedes usar una caja de cereales pequeña pintada de rojo como buzón oficial. Tiempo estimado de creación: 20 minutos.', 'Our elf knows there is nothing more beautiful than a handwritten greeting. He spent the night writing mini postcards for all the toys in the house and for the family, using an improvised mailbox so the kids can leave their own letters to Santa.' || char(10) || char(10) || 'You will need colored cardstock cut into tiny rectangles, handmade paper envelopes, and a fine-tip pen. You can use a small cereal box painted red as the official mailbox. Estimated creation time: 20 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(53, 'El Elfo-Adorno Resplandeciente', 'The Glittering Elf Ornament', '¡El elfo quiere ser la estrella de la fiesta! Se ha camuflado entre las ramas del árbol de Navidad, pero no de cualquier manera: se ha envuelto en espumillón brillante y se ha colgado de una rama mediante una bola decorativa, esperando a ver cuánto tardan en encontrarlo entre tanto brillo.' || char(10) || char(10) || 'Materiales: Espumillón de colores, una bola de Navidad (quítale el gancho para que el elfo pueda "sujetarla") y el propio árbol. Asegúrate de que el elfo esté seguro para que no se caiga durante la noche. Tiempo estimado de creación: 5 minutos.', 'The elf wants to be the star of the party! He has camouflaged himself among the Christmas tree branches, but not just any way: he has wrapped himself in shiny tinsel and hung from a branch using a decorative ball, waiting to see how long it takes for everyone to spot him among all the glitter.' || char(10) || char(10) || 'Materials: colorful tinsel, a Christmas ball (remove its hook so the elf can "hold" it), and the tree itself. Make sure the elf is secure so he doesn''t fall during the night. Estimated creation time: 5 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(15, 'Arquitectura en Jengibre', 'Gingerbread Architecture', '¡Es hora de construir! El elfo ha tomado el mando de la construcción de la casita de jengibre. Con un casco de obrero y planos de azúcar, está supervisando que cada gominola y cada gramo de glaseado estén en su lugar para que la estructura sea resistente a los mordiscos.' || char(10) || char(10) || 'Para esta escena puedes usar un kit de casa de jengibre real o construir una versión pequeña con galletas tipo "Maria" y chocolate fundido. Esparce azúcar glass alrededor para simular la nieve de la obra. Tiempo estimado de creación: 45 minutos.', 'Time to build! The elf has taken charge of the gingerbread house construction. Wearing a hard hat and holding sugar blueprints, he is supervising that every gummy candy and every gram of icing is in place so the structure can withstand any bites.' || char(10) || char(10) || 'For this scene you can use a real gingerbread house kit or build a small version with "Maria" type biscuits and melted chocolate. Scatter powdered sugar around to simulate construction-site snow. Estimated creation time: 45 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"FOOD"},{"label":"HARD"}]', 0),
(139, 'El Maestro del Papel de Regalo', 'The Gift Wrapping Master', 'Parece que el elfo tiene un exceso de celo con la seguridad de los regalos. Ha decidido "proteger" el mando de la televisión y los zapatos de los niños envolviéndolos meticulosamente en papel de regalo navideño, con lazos gigantes y etiquetas que ponen "¡No abrir hasta Navidad!".' || char(10) || char(10) || 'Materiales: Papel de regalo, celo y lazos. Elige un par de objetos cotidianos que los niños usen por la mañana para que la sorpresa sea más divertida al encontrarlos envueltos. Tiempo estimado de creación: 15 minutos.', 'It seems the elf is overly concerned about gift security. He has decided to "protect" the TV remote and the kids'' shoes by meticulously wrapping them in Christmas gift paper, complete with giant bows and tags reading "Do not open until Christmas!".' || char(10) || char(10) || 'Materials: gift wrapping paper, tape, and bows. Choose a couple of everyday objects that the kids use in the morning so the surprise is even more fun when they find them wrapped. Estimated creation time: 15 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(42, 'Operación Estrella Plateada', 'Operation Silver Star', 'Colocar la estrella en lo más alto del árbol es una misión crítica. El elfo ha construido una escalera de ingeniería usando bastones de caramelo atados con lazos rojos, y está a punto de coronar el árbol con una estrella brillante que él mismo ha "fabricado" con papel de aluminio.' || char(10) || char(10) || 'Necesitarás 4 o 6 bastones de caramelo largos, hilo o cordel para atarlos como los peldaños de una escalera y papel de aluminio para la estrella. Apoya la escalera con cuidado contra el árbol. Tiempo estimado de creación: 25 minutos.', 'Placing the star at the very top of the tree is a critical mission. The elf has built an engineering ladder using candy canes tied with red bows, and is about to crown the tree with a bright star he has "made" himself out of aluminum foil.' || char(10) || char(10) || 'You will need 4 or 6 long candy canes, thread or string to tie them as ladder rungs, and aluminum foil for the star. Lean the ladder carefully against the tree. Estimated creation time: 25 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(150, 'Coro de Juguetes Navideño', 'Christmas Toy Choir', '¡La música inunda el salón! El elfo ha reunido a todos los peluches y figuras de acción en una formación coral perfecta. Él está al frente, con una batuta y partituras minúsculas, dirigiendo a sus amigos en un ensayo general de villancicos clásicos.' || char(10) || char(10) || 'Materiales: Otros juguetes de la casa, un palillo de dientes como batuta y trozos de papel con notas musicales dibujadas. Puedes poner música navideña suave de fondo cuando los niños despierten. Tiempo estimado de creación: 15 minutos.', 'Music fills the living room! The elf has gathered all the stuffed animals and action figures into a perfect choir formation. He is at the front, baton in hand with tiny sheet music, conducting his friends in a full rehearsal of classic Christmas carols.' || char(10) || char(10) || 'Materials: other toys from around the house, a toothpick as a baton, and pieces of paper with musical notes drawn on them. You can play soft Christmas music in the background when the kids wake up. Estimated creation time: 15 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(75, 'El Elfo en la Bola de Nieve', 'The Elf in the Snow Globe', 'Nuestro amigo se ha quedado "atrapado" en un mundo mágico de cristal. Ha entrado en un tarro de cristal que simula una bola de nieve gigante, rodeado de purpurina y pequeños pinos, creando una de las estampas más decorativas y hermosas de toda la temporada.' || char(10) || char(10) || 'Necesitarás un tarro grande de cristal, purpurina blanca o plateada, y opcionalmente un poco de algodón para el suelo. Si quieres que sea una manualidad de larga duración, no añadas agua para no estropear al elfo. Tiempo estimado de creación: 10 minutos.', 'Our friend has gotten "trapped" in a magical crystal world. He has stepped inside a glass jar that simulates a giant snow globe, surrounded by glitter and tiny pine trees, creating one of the most decorative and beautiful scenes of the entire season.' || char(10) || char(10) || 'You will need a large glass jar, white or silver glitter, and optionally a little cotton for the floor. If you want this craft to last a long time, do not add water so the elf doesn''t get ruined. Estimated creation time: 10 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"SNOW"},{"label":"MEDIUM"}]', 0),
(83, 'La Cuenta Atrás Definitiva', 'The Ultimate Countdown', '¡El elfo está emocionado porque falta muy poco! Ha sido encontrado frente al calendario de Adviento, marcando con un rotulador rojo gigante los días que ya han pasado y señalando con entusiasmo el día de hoy, donde ha dejado una pequeña pista sobre la sorpresa del día.' || char(10) || char(10) || 'Solo necesitas el calendario de Adviento que ya tengas en casa y un rotulador. Si no tienes uno, puedes dibujar un calendario simple en una cartulina grande y dejar que el elfo lo "estrene". Tiempo estimado de creación: 5 minutos.', 'The elf is buzzing with excitement because the big day is almost here! He has been found in front of the Advent calendar, crossing off the days that have already passed with a giant red marker and enthusiastically pointing to today, where he has left a small clue about the day''s surprise.' || char(10) || char(10) || 'All you need is the Advent calendar you already have at home and a marker. If you don''t have one, you can draw a simple calendar on a large piece of cardstock and let the elf "inaugurate" it. Estimated creation time: 5 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"EASY"}]', 0),
(136, 'Enredado en la Iluminación', 'Tangled in the Lights', 'Las luces de Navidad pueden ser traicioneras. El elfo intentó añadir una hilera extra de bombillas al pasillo y ha terminado completamente enredado en un cable de luces LED. Ahora brilla con diferentes colores mientras espera que alguien lo desenrede de este lío luminoso.' || char(10) || char(10) || 'Materiales: Una guirnalda de luces LED (preferiblemente a pilas para mayor seguridad). Envuelve al elfo de forma caótica pero segura, y asegúrate de que las luces no se calienten demasiado. Tiempo estimado de creación: 10 minutos.', 'Christmas lights can be treacherous. The elf tried to add an extra string of bulbs to the hallway and ended up completely tangled in an LED light cable. He is now glowing in different colors while waiting for someone to untangle him from this luminous mess.' || char(10) || char(10) || 'Materials: an LED light garland (preferably battery-powered for safety). Wrap the elf chaotically but securely, and make sure the lights do not get too warm. Estimated creation time: 10 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0),
(79, 'Visitante del Portal de Belén', 'Visitor at the Nativity Scene', 'Con mucho respeto, el elfo ha ido a visitar el portal de Belén. Ha traído un pequeño regalo envuelto para colocarlo junto a los de los Reyes Magos y se ha quedado allí, charlando con los pastores y admirando la escena en un momento de paz navideña.' || char(10) || char(10) || 'Necesitarás el portal de Belén de casa y un cuadradito de papel de regalo con un lazo para el obsequio del elfo. Colócalo de forma que no desentone con las figuras tradicionales para un efecto más tierno. Tiempo estimado de creación: 5 minutos.', 'With great respect, the elf has gone to visit the Nativity scene. He has brought a small wrapped gift to place alongside those of the Three Wise Men and has stayed there, chatting with the shepherds and admiring the scene in a moment of Christmas peace.' || char(10) || char(10) || 'You will need the Nativity scene from home and a small square of gift paper with a bow for the elf''s offering. Place him in a way that blends naturally with the traditional figures for a more heartwarming effect. Estimated creation time: 5 minutes.', 'elf_festival', '[{"label":"FESTIVAL"},{"label":"MYSTERY"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(32, 'El Mensaje de Tinta Invisible', 'The Invisible Ink Message', '¡Misterio absoluto! El elfo ha dejado una hoja de papel completamente en blanco sobre la mesa junto a un pincel y un pequeño cuenco con un líquido transparente. Solo los niños más astutos podrán revelar el mensaje secreto que ha enviado directamente desde el cuartel general de Santa.' || char(10) || char(10) || 'Para esta manualidad necesitarás zumo de limón o una cera blanca. Escribe el mensaje en el papel; si usas limón, los niños deberán aplicar calor (con cuidado) o acuarelas para verlo. Si usas cera blanca, bastará con pintar encima con rotuladores. Tiempo estimado de creación: 10 minutos.', 'Absolute mystery! The elf has left a completely blank sheet of paper on the table next to a paintbrush and a small bowl of transparent liquid. Only the sharpest kids will be able to reveal the secret message he has sent directly from Santa''s headquarters.' || char(10) || char(10) || 'For this craft you will need lemon juice or a white wax crayon. Write the message on the paper; if you use lemon, the kids will need to apply heat (carefully) or watercolors to see it. If you use a white crayon, simply painting over it with markers will do the trick. Estimated creation time: 10 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"EASY"},{"label":"LIVINGROOM"}]', 0),
(103, 'Escena del Crimen: La Galleta Desaparecida', 'Crime Scene: The Missing Cookie', '¡Alguien ha robado la galleta de medianoche! El elfo ha acordonado una zona de la encimera con cinta de "No pasar" y ha marcado con tiza la silueta del dulce desaparecido. Hay migas sospechosas que delatan al culpable, y nuestro elfo está tomando muestras con una lupa en mano.' || char(10) || char(10) || 'Materiales: Harina o tiza para dibujar la silueta, cinta aislante de color llamativo para el cordón policial y migas de galleta real. Puedes añadir una lupa de juguete para que el elfo parezca un profesional. Tiempo estimado de creación: 15 minutos.', 'Someone has stolen the midnight cookie! The elf has cordoned off a section of the counter with "Do not cross" tape and chalked the outline of the missing treat. There are suspicious crumbs pointing to the culprit, and our elf is collecting samples with a magnifying glass in hand.' || char(10) || char(10) || 'Materials: flour or chalk to draw the outline, brightly colored insulating tape for the police cordon, and real cookie crumbs. You can add a toy magnifying glass to make the elf look like a true professional. Estimated creation time: 15 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(22, 'El Enigma del Código César', 'The Caesar Code Enigma', 'El elfo ha dejado una nota cifrada llena de símbolos extraños y números. Para descubrir dónde ha escondido el desayuno de hoy, los niños deberán usar un disco decodificador que el elfo ha construido a medias, retándolos a completar la lógica del mensaje antes de que se enfríe la leche.' || char(10) || char(10) || 'Necesitarás dos círculos de cartulina de diferentes tamaños unidos por un encuadernador con el abecedario escrito. Deja una pista visual de cuál es la letra clave (por ejemplo, una "A" alineada con una "D"). Tiempo estimado de creación: 25 minutos.', 'The elf has left an encoded note full of strange symbols and numbers. To find out where he has hidden today''s breakfast, the kids must use a decoder wheel that the elf has half-built, challenging them to complete the logic of the message before the milk goes cold.' || char(10) || char(10) || 'You will need two cardstock circles of different sizes joined with a brass fastener, with the alphabet written on each. Leave a visual clue as to which is the key letter (for example, an "A" aligned with a "D"). Estimated creation time: 25 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"HARD"},{"label":"KITCHEN"}]', 0),
(10, 'La Huella del Intruso Gigante', 'The Giant Intruder''s Footprint', '¡Una huella enorme ha aparecido en el pasillo! El elfo está analizando la marca con cara de preocupación, comparándola con el tamaño de su propio pie. Parece que un visitante misterioso (¿un Yeti? ¿Santa?) ha entrado en la casa mientras todos dormían y el elfo está siguiendo el rastro.' || char(10) || char(10) || 'Materiales: Harina o polvos talco para crear la forma de una pisada grande en el suelo. Usa una bota de adulto para presionar sobre el polvo y crear la forma perfecta. Coloca al elfo junto a la huella con una cinta métrica. Tiempo estimado de creación: 5 minutos.', 'A huge footprint has appeared in the hallway! The elf is analyzing the mark with a worried look, comparing it to the size of his own foot. It seems a mysterious visitor (a Yeti? Santa?) entered the house while everyone was sleeping and the elf is now following the trail.' || char(10) || char(10) || 'Materials: flour or talcum powder to create the shape of a large footprint on the floor. Use an adult boot to press into the powder and create the perfect shape. Place the elf next to the footprint with a measuring tape. Estimated creation time: 5 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"SNOW"},{"label":"EASY"}]', 0),
(35, 'El Caso de la Llave Encadenada', 'The Case of the Chained Key', 'El elfo sostiene una llave antigua atada a su muñeca, pero no hay ninguna cerradura a la vista. Ha dejado una serie de fotos o dibujos de rincones de la casa que, al unirlos, revelan la ubicación del cofre misterioso que esa llave abre. ¡La búsqueda ha comenzado!' || char(10) || char(10) || 'Necesitarás una llave vieja, un cordel y una caja pequeña con un candado (o cerrada con mucha cinta). Esconde la caja en un lugar difícil y deja pistas fotográficas por el salón. Tiempo estimado de creación: 20 minutos.', 'The elf is holding an old key tied to his wrist, but there is no lock in sight. He has left a series of photos or drawings of corners of the house that, when pieced together, reveal the location of the mysterious chest that key unlocks. The search has begun!' || char(10) || char(10) || 'You will need an old key, a piece of string, and a small box with a padlock (or sealed with plenty of tape). Hide the box somewhere tricky and leave photographic clues around the living room. Estimated creation time: 20 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"TREASURE"},{"label":"MEDIUM"}]', 0),
(144, 'La Sombra del Espía Nocturno', 'The Shadow of the Night Spy', 'Una silueta misteriosa se proyecta en la pared del pasillo. Al encender la luz, los niños descubrirán que el elfo ha montado un teatro de sombras chinas detrás de una sábana tensada, ocultando su verdadera posición y dejando solo un perfil enigmático que parece vigilar el árbol.' || char(10) || char(10) || 'Materiales: Una linterna potente, una sábana blanca o papel cebolla y una estructura para sujetarlo. Coloca al elfo entre la luz y la tela para que su sombra se vea gigante en la pared. Tiempo estimado de creación: 15 minutos.', 'A mysterious silhouette is projected onto the hallway wall. When the kids turn on the light, they will discover that the elf has set up a shadow puppet theater behind a stretched sheet, hiding his true position and leaving only an enigmatic profile that seems to be watching over the tree.' || char(10) || char(10) || 'Materials: a powerful flashlight, a white sheet or tracing paper, and a structure to hold it taut. Place the elf between the light and the fabric so his shadow appears giant on the wall. Estimated creation time: 15 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"MEDIUM"},{"label":"LIVINGROOM"}]', 0),
(112, 'Laboratorio de Huellas Dactilares', 'Fingerprint Laboratory', '¡Investigación forense en el baño! El elfo ha encontrado huellas dactilares "sospechosas" en el espejo y las ha cubierto con polvos mágicos para identificarlas. Tiene una lista de sospechosos con las huellas de todos los miembros de la familia para encontrar al responsable de gastar el jabón.' || char(10) || char(10) || 'Necesitarás cacao en polvo o polvos talco, un pincel suave y celo transparente para "levantar" las huellas del cristal. Prepara una ficha de cartulina con las huellas reales de la familia para comparar. Tiempo estimado de creación: 30 minutos.', 'Forensic investigation in the bathroom! The elf has found "suspicious" fingerprints on the mirror and has dusted them with magic powder to identify them. He has a suspect list with the fingerprints of every family member to track down who is responsible for using up all the soap.' || char(10) || char(10) || 'You will need cocoa powder or talcum powder, a soft brush, and clear tape to "lift" the prints from the glass. Prepare a cardstock card with the family''s real fingerprints for comparison. Estimated creation time: 30 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"BATHROOM"},{"label":"HARD"}]', 0),
(48, 'El Secuestro de los Juguetes Favoritos', 'The Kidnapping of the Favorite Toys', '¡Alerta roja! Los peluches favoritos de los niños han aparecido con los ojos vendados y las manos atadas (suavemente). El elfo está sentado en una silla de mando, con una máscara de detective, exigiendo que se resuelva un acertijo para liberar a los rehenes del juego.' || char(10) || char(10) || 'Materiales: Otros juguetes, tiras de tela para las vendas y una nota con un acertijo rimado. Asegúrate de que los nudos sean fáciles de desatar para los niños. Tiempo estimado de creación: 10 minutos.', 'Red alert! The kids'' favorite stuffed animals have turned up blindfolded and gently tied up. The elf is sitting in a command chair, wearing a detective mask, demanding that a riddle be solved to free the toy hostages.' || char(10) || char(10) || 'Materials: other toys, strips of fabric for the blindfolds, and a note with a rhyming riddle. Make sure the knots are easy for the kids to undo. Estimated creation time: 10 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0),
(125, 'El Puzzle del Mensaje Perdido', 'The Lost Message Puzzle', 'El elfo ha roto su mensaje importante en 10 trozos y los ha esparcido por toda la habitación. Los niños deberán encontrar todas las piezas y encajarlas como un puzzle para leer la advertencia urgente que el elfo ha traído desde el taller de juguetes.' || char(10) || char(10) || 'Solo necesitas una hoja de papel con un dibujo o mensaje colorido. Córtala en formas irregulares y escóndelas en lugares visibles pero estratégicos. El elfo debe sostener la pieza central. Tiempo estimado de creación: 15 minutos.', 'The elf has torn his important message into 10 pieces and scattered them all around the room. The kids must find all the pieces and fit them together like a puzzle to read the urgent warning the elf has brought from the toy workshop.' || char(10) || char(10) || 'All you need is a sheet of paper with a colorful drawing or message. Cut it into irregular shapes and hide them in visible but strategic spots. The elf should be holding the central piece. Estimated creation time: 15 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"EASY"},{"label":"BEDROOM"}]', 0),
(95, 'El Código del Espejo Empañado', 'The Foggy Mirror Code', 'Un mensaje fantasmagórico ha aparecido en el espejo del baño. No se ve nada a simple vista, pero cuando el ambiente se calienta, las letras empiezan a brillar. El elfo está sentado sobre el grifo, esperando a que alguien se duche para que el secreto sea revelado.' || char(10) || char(10) || 'Para este truco, escribe un mensaje en el espejo seco usando un poco de jabón de manos en el dedo o un bastoncillo. Cuando el espejo se empañe con el vapor, el mensaje quedará limpio y será legible. Tiempo estimado de creación: 5 minutos.', 'A ghostly message has appeared on the bathroom mirror. Nothing is visible to the naked eye, but when the room warms up, the letters start to glow. The elf is sitting on the faucet, waiting for someone to take a shower so the secret can be revealed.' || char(10) || char(10) || 'For this trick, write a message on the dry mirror using a little hand soap on your finger or a cotton swab. When the mirror fogs up with steam, the message will appear clean and readable. Estimated creation time: 5 minutes.', 'elf_mystery', '[{"label":"MYSTERY"},{"label":"BATHROOM"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(107, 'Patinaje Artístico sobre Espejo', 'Artistic Skating on the Mirror', '¡El elfo ha montado una pista de patinaje profesional en el salón! Aprovechando una superficie reflectante, ha estado practicando piruetas y ochos durante toda la noche. Se le encuentra en una pose de equilibrio perfecta, rodeado de montículos de nieve que brillan bajo las luces del árbol.' || char(10) || char(10) || 'Necesitarás un espejo de mano o de pared colocado horizontalmente, dos clips metálicos pegados a los pies del elfo como patines y una buena cantidad de bicarbonato de sodio o purpurina blanca para los bordes. Tiempo estimado de creación: 10 minutos.', 'The elf has set up a professional skating rink in the living room! Taking advantage of a reflective surface, he has been practicing spins and figure eights all night long. He is found in a perfectly balanced pose, surrounded by snow mounds glistening under the tree lights.' || char(10) || char(10) || 'You will need a handheld or wall mirror placed horizontally, two metal paper clips attached to the elf''s feet as skates, and a generous amount of baking soda or white glitter along the edges. Estimated creation time: 10 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(121, 'Guerra de Bolas de Nieve Dulces', 'Sweet Snowball Fight', '¡Se ha desatado una batalla épica! El elfo se ha atrincherado detrás de un fuerte de cajas de cartón y está lanzando proyectiles blancos contra un grupo de peluches. El suelo está cubierto de munición y parece que nuestro amigo lleva la delantera en este enfrentamiento ártico.' || char(10) || char(10) || 'Materiales: Mini malvaviscos (nubes) esparcidos por el suelo, una caja de pañuelos vacía para el fuerte y otros juguetes para hacer de oponentes. Crea pequeñas pirámides de malvaviscos para que parezcan pilas de bolas de nieve listas para usar. Tiempo estimado de creación: 15 minutos.', 'An epic battle has broken out! The elf has barricaded himself behind a cardboard box fort and is hurling white projectiles at a group of stuffed animals. The floor is covered in ammunition and it looks like our friend is winning this arctic showdown.' || char(10) || char(10) || 'Materials: mini marshmallows scattered on the floor, an empty tissue box for the fort, and other toys to act as opponents. Build small marshmallow pyramids to look like piles of snowballs ready to be thrown. Estimated creation time: 15 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(101, 'El Iglú de Terrones de Azúcar', 'The Sugar Cube Igloo', 'Nuestro ingeniero polar ha construido un refugio tradicional para protegerse de las corrientes de aire nocturnas. Es un iglú estructuralmente perfecto, con su cúpula y túnel de entrada, donde el elfo descansa tranquilamente asomando solo su gorro rojo por la puerta.' || char(10) || char(10) || 'Necesitarás una caja de terrones de azúcar cuadrados y un poco de glaseado real o pegamento escolar para unir las piezas. Puedes usar un tazón del revés como base para pegar los terrones alrededor y darle la forma curva. Tiempo estimado de creación: 40 minutos.', 'Our polar engineer has built a traditional shelter to protect himself from the night-time draughts. It is a structurally perfect igloo, complete with its dome and entry tunnel, where the elf rests peacefully with only his red hat peeking out through the doorway.' || char(10) || char(10) || 'You will need a box of square sugar cubes and a little royal icing or school glue to join the pieces. You can use an upside-down bowl as a base to press the cubes around and give it the curved dome shape. Estimated creation time: 40 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"KITCHEN"},{"label":"HARD"}]', 0),
(113, 'Esquí Alpino en la Barandilla', 'Alpine Skiing on the Banister', '¡La barandilla de la escalera se ha convertido en una pista de esquí de alta velocidad! El elfo ha bajado a toda prisa con sus esquís de madera, dejando un rastro de nieve tras de sí y logrando un salto acrobático justo antes de llegar al suelo del pasillo.' || char(10) || char(10) || 'Materiales: Dos palitos de helado para los esquís, dos palillos de dientes para los bastones y algodón estirado a lo largo de la barandilla para simular la nieve. Sujeta al elfo con un poco de cinta de doble cara para que no se deslice de verdad. Tiempo estimado de creación: 20 minutos.', 'The staircase banister has become a high-speed ski slope! The elf has rushed down on his wooden skis, leaving a trail of snow behind him and pulling off an acrobatic jump just before reaching the hallway floor.' || char(10) || char(10) || 'Materials: two popsicle sticks for skis, two toothpicks for ski poles, and cotton stretched along the banister to simulate snow. Secure the elf with a little double-sided tape so he doesn''t actually slide down. Estimated creation time: 20 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(88, 'Un Ángel en la Ventisca de Harina', 'A Snow Angel in the Flour Blizzard', 'El elfo no ha podido resistirse a la nieve fresca. Se ha tumbado en medio de la cocina y ha movido sus brazos y piernas con entusiasmo para dejar la marca de un ángel perfecto. Está cubierto de polvo blanco de la cabeza a los pies, como si acabara de salir de una tormenta.' || char(10) || char(10) || 'Solo necesitas harina de trigo o azúcar glass esparcida sobre una bandeja oscura o la encimera. Coloca al elfo y mueve sus extremidades para marcar la silueta antes de dejarlo allí "descansando". Tiempo estimado de creación: 5 minutos.', 'The elf could not resist the fresh snow. He lay down in the middle of the kitchen and enthusiastically moved his arms and legs to leave the perfect snow angel imprint. He is covered in white powder from head to toe, as if he has just stepped out of a blizzard.' || char(10) || char(10) || 'All you need is plain flour or powdered sugar scattered over a dark tray or the countertop. Place the elf and move his limbs to mark the silhouette before leaving him there "resting". Estimated creation time: 5 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(100, 'El Elfo Criogenizado en el Hielo', 'The Cryogenized Elf in the Ice', '¡Misterio en el congelador! El elfo ha sido encontrado atrapado dentro de un bloque de hielo sólido. Parece que intentó investigar dónde se guardaban los helados y se quedó congelado en el tiempo, esperando a que el calor de la mañana lo libere de su prisión transparente.' || char(10) || char(10) || 'Necesitarás un recipiente de plástico grande con agua donde quepa el elfo (¡protégelo primero con una bolsa de plástico hermética tipo Zip!). Déjalo en el congelador toda la noche y sácalo justo antes de que los niños despierten. Tiempo estimado de creación: 5 minutos (más 8h de congelación).', 'Mystery in the freezer! The elf has been found trapped inside a solid block of ice. It seems he tried to investigate where the ice cream was kept and got frozen in time, waiting for the morning warmth to free him from his transparent prison.' || char(10) || char(10) || 'You will need a large plastic container filled with water that the elf fits inside (first protect him in a sealed zip-lock bag!). Leave it in the freezer overnight and take it out just before the kids wake up. Estimated creation time: 5 minutes (plus 8 hours freezing time).', 'elf_snow', '[{"label":"SNOW"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0),
(118, 'Pesca Milagrosa en el Agujero de Hielo', 'Ice Hole Miracle Fishing', 'Sentado sobre una superficie blanca y fría, el elfo está practicando la pesca en el hielo. Ha hecho un agujero perfecto y ha lanzado su sedal, esperando pacientemente a que algún pez de las profundidades árticas pique el anzuelo en esta mañana invernal.' || char(10) || char(10) || 'Materiales: Un trozo de fieltro blanco o una cartulina con un agujero azul en el centro, un palito de brocheta como caña y un pececito de gominola o cartulina atado a un hilo dental. Colócalo sobre una mesa o el suelo del baño. Tiempo estimado de creación: 10 minutos.', 'Sitting on a cold white surface, the elf is practicing ice fishing. He has made a perfect hole and cast his line, patiently waiting for a fish from the arctic depths to take the bait on this wintry morning.' || char(10) || char(10) || 'Materials: a piece of white felt or cardstock with a blue hole cut in the center, a skewer stick as a fishing rod, and a gummy or cardstock fish tied to a length of dental floss. Place it on a table or the bathroom floor. Estimated creation time: 10 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"BATHROOM"},{"label":"EASY"}]', 0),
(30, 'Disfraz de Muñeco de Nieve', 'Snowman Costume', 'El elfo ha decidido que hoy quiere ser un muñeco de nieve. Se ha envuelto en capas de algodón blanco y se ha puesto una nariz de zanahoria diminuta, mimetizándose con un grupo de amigos hechos de nieve que ha construido para que le hagan compañía en el recibidor.' || char(10) || char(10) || 'Utiliza bolas de algodón para cubrir el cuerpo del elfo, pegándolas ligeramente. Haz otros dos muñecos de nieve solo con algodón y ponles botones de verdad o trozos de cartulina negra para los ojos. Tiempo estimado de creación: 15 minutos.', 'The elf has decided that today he wants to be a snowman. He has wrapped himself in layers of white cotton and put on a tiny carrot nose, blending in with a group of snowy friends he has built to keep him company in the entryway.' || char(10) || char(10) || 'Use cotton balls to cover the elf''s body, attaching them lightly. Make two other snowmen using only cotton and give them real buttons or small pieces of black cardstock for eyes. Estimated creation time: 15 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"FESTIVAL"},{"label":"MEDIUM"}]', 0),
(85, 'Descenso en Trineo de Plato de Papel', 'Paper Plate Sled Descent', '¡A toda máquina! El elfo está bajando por una montaña de cojines blancos montado en un trineo circular. Lleva una bufanda de lana que vuela con el viento y una expresión de pura alegría mientras se desliza hacia la base de la "montaña" nevada del salón.' || char(10) || char(10) || 'Necesitarás un plato de papel pequeño doblado para que parezca un trineo de disco, cojines blancos apilados y una bufanda de tela o lana. Usa hilo de pescar para que el trineo parezca estar en el aire durante el salto. Tiempo estimado de creación: 10 minutos.', 'Full speed ahead! The elf is sledding down a mountain of white cushions on a circular sled. He is wearing a wool scarf flying in the wind, with an expression of pure joy as he glides toward the base of the snowy "mountain" in the living room.' || char(10) || char(10) || 'You will need a small paper plate folded to look like a disc sled, stacked white cushions, and a fabric or wool scarf. Use fishing line to make the sled look like it is airborne during the jump. Estimated creation time: 10 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(106, 'Expedición al Pico de la Nevera', 'Expedition to the Fridge Peak', 'La parte superior del frigorífico es el punto más alto del mapa ártico de la cocina. El elfo ha llegado a la cumbre tras una dura escalada y ha plantado una bandera de expedición, rodeado de estalactitas de hielo que cuelgan del borde como en una cueva real.' || char(10) || char(10) || 'Materiales: Papel de plata o celofán transparente arrugado para simular el hielo, un palillo de dientes con una bandera de papel y algodón para la base de la cumbre. Es una escena ideal para aprovechar la altura de la cocina. Tiempo estimado de creación: 15 minutos.', 'The top of the fridge is the highest point on the kitchen''s arctic map. The elf has reached the summit after a tough climb and planted an expedition flag, surrounded by ice stalactites hanging from the edge just like a real cave.' || char(10) || char(10) || 'Materials: crumpled silver foil or transparent cellophane to simulate ice, a toothpick with a paper flag, and cotton for the summit base. It is an ideal scene to make the most of the kitchen''s height. Estimated creation time: 15 minutes.', 'elf_snow', '[{"label":"SNOW"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(143, 'Cine en la Mesita de Noche', 'Bedside Table Cinema', '¡Es noche de estreno! El elfo ha organizado una sesión de cine privado para los peluches favoritos de los niños. Ha usado un teléfono móvil o una tablet como pantalla gigante y ha repartido mini cubos de palomitas para que todos disfruten de una película navideña antes de dormir.' || char(10) || char(10) || 'Materiales necesarios: Un dispositivo móvil, juguetes pequeños, y tapones de botella llenos de palomitas reales o trocitos de papel blanco arrugado. Coloca al elfo en la "fila VIP" con su propio combo de comida. Tiempo estimado de creación: 10 minutos.', 'It is premiere night! The elf has organized a private cinema screening for the kids'' favorite stuffed animals. He has used a mobile phone or tablet as a giant screen and handed out mini popcorn buckets so everyone can enjoy a Christmas movie before bedtime.' || char(10) || char(10) || 'Materials needed: a mobile device, small toys, and bottle caps filled with real popcorn or crumpled white paper pieces. Place the elf in the "VIP row" with his own food combo. Estimated creation time: 10 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(91, 'Lectura de Cuentos a la Luz de la Vela', 'Storytime by Candlelight', 'Nuestro elfo es un gran amante de la literatura. Se le ha encontrado sentado sobre la almohada, leyendo un cuento infantil a un grupo de figuras de acción. Para no despertar a nadie, está usando una pequeña vela de té para iluminar las páginas del libro.' || char(10) || char(10) || 'Necesitarás un libro de cuentos abierto y una vela de té LED (nunca real). Coloca al elfo con las manos sobre las páginas como si estuviera pasando la hoja. Es una escena muy tierna para colocar junto a la cabeza del niño. Tiempo estimado de creación: 5 minutos.', 'Our elf is a great lover of literature. He has been found sitting on the pillow, reading a children''s story to a group of action figures. To avoid waking anyone up, he is using a small tea candle to light the pages of the book.' || char(10) || char(10) || 'You will need an open storybook and an LED tea candle (never a real one). Place the elf with his hands on the pages as if he is turning them. It is a very tender scene to set up next to the child''s head. Estimated creation time: 5 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"FESTIVAL"},{"label":"EASY"}]', 0),
(25, 'El Taller de Costura de Calcetines', 'The Sock Sewing Workshop', '¡Travesura textil! El elfo ha decidido que los calcetines del niño necesitaban un toque navideño. Ha sacado un kit de costura y está intentando coser cascabeles y lazos rojos a los calcetines escolares, rodeado de hilos de colores que se han enredado por toda la colcha.' || char(10) || char(10) || 'Materiales: Un par de calcetines, hilo, aguja (de juguete o con punta roma por seguridad) y algunos cascabeles o cintas. Esparce el hilo por la cama para simular el caos creativo del elfo. Tiempo estimado de creación: 15 min.', 'Textile mischief! The elf has decided that the child''s socks needed a festive touch. He has pulled out a sewing kit and is trying to stitch bells and red ribbons onto the school socks, surrounded by colorful threads tangled all over the duvet.' || char(10) || char(10) || 'Materials: a pair of socks, thread, a needle (toy or blunt-tipped for safety), and some bells or ribbons. Spread the thread across the bed to simulate the elf''s creative chaos. Estimated creation time: 15 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"CLOTHES"},{"label":"MEDIUM"}]', 0),
(74, 'Acampada de Interior en el Edredón', 'Indoor Camping on the Duvet', 'El edredón de la cama se ha convertido en una cordillera de montañas blancas. El elfo ha montado su propia tienda de campaña con un pañuelo y está asomado con una linterna, vigilando que no aparezca ningún "monstruo debajo de la cama" mientras los niños duermen.' || char(10) || char(10) || 'Necesitarás un pañuelo de cuello, dos lápices para hacer los postes de la tienda y una linterna pequeña. Colócalo sobre la manta o la colcha para que parezca un campamento base en el Everest. Tiempo estimado de creación: 10 minutos.', 'The bed duvet has become a mountain range of white peaks. The elf has pitched his own tent using a handkerchief and is peering out with a flashlight, keeping watch to make sure no "monster under the bed" appears while the kids sleep.' || char(10) || char(10) || 'You will need a neck scarf, two pencils to make the tent poles, and a small flashlight. Place it on top of the blanket or duvet to make it look like a base camp on Everest. Estimated creation time: 10 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(47, 'SPA con Rodajas de Pepino', 'Cucumber Slice SPA', 'El estrés de vigilar la casa es agotador. El elfo se ha tomado un descanso en la mesita de noche; está tumbado sobre una toallita de mano, con un albornoz hecho de papel higiénico y dos rodajas de pepino (o papel verde) sobre sus ojos para reducir el cansancio.' || char(10) || char(10) || 'Materiales: Una toalla pequeña, papel higiénico y dos círculos de cartulina verde o pepino real. Puedes poner música relajante de fondo con un altavoz inteligente para completar la escena matutina. Tiempo estimado de creación: 10 minutos.', 'The stress of watching over the house is exhausting. The elf has taken a break on the bedside table; he is lying on a hand towel, wearing a bathrobe made of toilet paper and two cucumber slices (or green paper circles) over his eyes to reduce fatigue.' || char(10) || char(10) || 'Materials: a small towel, toilet paper, and two green cardstock circles or real cucumber slices. You can play relaxing background music on a smart speaker to complete the morning scene. Estimated creation time: 10 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(80, 'La Gran Carrera de Peluches', 'The Great Stuffed Animal Race', '¡El dormitorio se ha convertido en un circuito de carreras! El elfo ha organizado una competición donde los coches son zapatos y los pilotos son los peluches más rápidos de la habitación. Él está en la meta, agitando una bandera de cuadros y sosteniendo un trofeo dorado.' || char(10) || char(10) || 'Necesitarás varios zapatos de los niños, peluches pequeños, papel para hacer la bandera y un dedal que sirva como trofeo. Alinea los zapatos en el suelo del dormitorio creando una parrilla de salida. Tiempo estimado de creación: 15 minutos.', 'The bedroom has become a racing circuit! The elf has organized a competition where the cars are shoes and the drivers are the fastest stuffed animals in the room. He is at the finish line, waving a checkered flag and holding a golden trophy.' || char(10) || char(10) || 'You will need several of the kids'' shoes, small stuffed animals, paper to make the flag, and a thimble to serve as the trophy. Line the shoes up on the bedroom floor to create a starting grid. Estimated creation time: 15 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(81, 'Mensaje con Estrellas Fluorescentes', 'Message with Fluorescent Stars', 'Aprovechando que los niños duermen, el elfo ha pegado estrellas fluorescentes en el techo o en el cabecero de la cama formando un mensaje secreto o su propio nombre. Está colgado del interruptor de la luz, esperando a que apaguen las luces para que su obra brille.' || char(10) || char(10) || 'Materiales: Estrellas de plástico luminiscentes o pegatinas que brillan en la oscuridad. Asegúrate de que las estrellas reciban luz durante el día para que la sorpresa funcione perfectamente por la noche. Tiempo estimado de creación: 20 minutos.', 'Taking advantage of the kids being asleep, the elf has stuck fluorescent stars on the ceiling or the headboard forming a secret message or his own name. He is hanging from the light switch, waiting for the lights to go out so his masterpiece can shine.' || char(10) || char(10) || 'Materials: luminescent plastic stars or glow-in-the-dark stickers. Make sure the stars get enough light during the day so the surprise works perfectly at night. Estimated creation time: 20 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(38, 'Asalto al Joyero de Juguetes', 'Raid on the Toy Jewellery Box', '¡El elfo ha encontrado el tesoro! Se ha metido dentro del joyero o la caja de tesoros de los niños y se ha puesto todos los collares, anillos y coronas de plástico que ha encontrado. Ahora brilla más que el propio árbol de Navidad desde la cómoda del dormitorio.' || char(10) || char(10) || 'Solo necesitas el joyero de los niños y sus accesorios de disfraz. Envuelve al elfo con los collares de cuentas y ponle una tiara si cabe en su cabeza. Es una imagen muy divertida y brillante. Tiempo estimado de creación: 5 minutos.', 'The elf has found the treasure! He has climbed inside the kids'' jewellery box or treasure chest and put on every plastic necklace, ring, and crown he could find. He now sparkles more than the Christmas tree itself from the bedroom dresser.' || char(10) || char(10) || 'All you need is the kids'' jewellery box and their dress-up accessories. Wrap the elf in bead necklaces and pop a tiara on his head if it fits. It is a very funny and glittery scene. Estimated creation time: 5 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"TREASURE"},{"label":"EASY"}]', 0),
(148, 'Peluquería Nocturna de Muñecas', 'Midnight Doll Hairdresser', 'El elfo ha abierto una peluquería de lujo en el cuarto de juegos. Ha sentado a todas las muñecas en fila y les ha puesto rulos (hechos de pajitas) y capas de peluquería (servilletas). Él está sosteniendo un peine, listo para hacer el cambio de look más radical de la temporada.' || char(10) || char(10) || 'Materiales: Muñecas, pajitas cortadas en trozos pequeños para los rulos, servilletas de papel y un peine pequeño. Puedes añadir un poco de confeti para simular "pelo mágico" cortado. Tiempo estimado de creación: 25 minutos.', 'The elf has opened a luxury hair salon in the playroom. He has sat all the dolls in a row and given them curlers (made from straws) and hairdressing capes (napkins). He is holding a comb, ready to deliver the most radical makeover of the season.' || char(10) || char(10) || 'Materials: dolls, straws cut into small pieces for the curlers, paper napkins, and a small comb. You can add a little confetti to simulate magically cut "hair". Estimated creation time: 25 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"CLOTHES"},{"label":"HARD"}]', 0),
(11, 'Escondite en la Lámpara de Noche', 'Hiding in the Night Lamp', '¡Casi no se le ve! El elfo se ha pegado a la parte interior de la pantalla de la lámpara. Cuando los niños enciendan la luz por la mañana, verán su silueta proyectada a través de la tela, dándoles un susto cariñoso o una sorpresa luminosa para empezar el día.' || char(10) || char(10) || 'Necesitarás cinta adhesiva fuerte (tipo de carrocero para no dañar la lámpara) y colocar al elfo entre la bombilla y la pantalla. ¡Importante! Usa bombillas LED que no emitan calor para evitar cualquier riesgo de quemadura. Tiempo estimado de creación: 5 minutos.', 'You can barely see him! The elf has attached himself to the inside of the lampshade. When the kids turn on the light in the morning, they will see his silhouette projected through the fabric, giving them a loving little fright or a glowing surprise to start the day.' || char(10) || char(10) || 'You will need strong adhesive tape (painter''s tape works well to avoid damaging the lamp) and place the elf between the bulb and the shade. Important: always use LED bulbs that do not emit heat to avoid any risk of burning. Estimated creation time: 5 minutes.', 'elf_bedroom', '[{"label":"BEDROOM"},{"label":"MYSTERY"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(114, 'Atrapado en la Trituradora de Papel', 'Trapped in the Paper Shredder', '¡Emergencia en la oficina de casa! El elfo ha intentado investigar cómo funciona la trituradora de papel y se ha quedado atrapado por la parte inferior de su traje. Con una expresión de pánico absoluto, sostiene un cartel que dice "¡Sacadme de aquí antes de que me convierta en confeti!"' || char(10) || char(10) || 'Materiales necesarios: Una trituradora de papel (¡desenchufada!), unos trozos de papel a medio triturar asomando y un pequeño cartel escrito a mano. Introduce la parte inferior del elfo entre las cuchillas detenidas. Tiempo estimado de creación: 5 minutos.', 'Home office emergency! The elf tried to investigate how the paper shredder works and got the bottom of his outfit caught in it. With an expression of absolute panic, he is holding a sign that reads "Get me out of here before I turn into confetti!"' || char(10) || char(10) || 'Materials needed: a paper shredder (always unplugged!), some half-shredded paper poking out, and a small handwritten sign. Insert the bottom of the elf between the stopped blades. Estimated creation time: 5 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"EASY"}]', 0),
(16, 'El Suelo es Lava: Versión Salón', 'The Floor is Lava: Living Room Edition', 'El elfo se ha tomado muy en serio el juego de "El suelo es lava". Ha cruzado todo el salón saltando de mueble en mueble y ahora se encuentra suspendido de un hilo de pescar sobre una alfombra roja que simula el magma volcánico, gritando por un rescate inminente.' || char(10) || char(10) || 'Necesitarás cartulina roja o una manta roja para el suelo, hilo de pescar para colgar al elfo del techo o de una lámpara, y algunos juguetes "atrapados" en la lava a su alrededor. Tiempo estimado de creación: 15 minutos.', 'The elf has taken the "floor is lava" game very seriously. He has crossed the entire living room leaping from furniture to furniture and is now suspended on fishing line above a red rug simulating volcanic magma, screaming for immediate rescue.' || char(10) || char(10) || 'You will need red cardstock or a red blanket for the floor, fishing line to hang the elf from the ceiling or a lamp, and some toys "trapped" in the lava around him. Estimated creation time: 15 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(69, 'Misión Imposible: El Ventilador de Techo', 'Mission Impossible: The Ceiling Fan', 'Nuestro agente secreto ha intentado realizar una infiltración aérea usando las aspas del ventilador de techo como plataforma de desembarco. Se encuentra agarrado con una sola mano a una de las aspas, mientras su cuerpo cuelga peligrosamente sobre la mesa del comedor.' || char(10) || char(10) || 'Materiales: Un ventilador de techo (apagado y con el interruptor bloqueado) y un poco de masilla adhesiva para asegurar la mano del elfo al aspa. Asegúrate de que nadie lo encienda por error. Tiempo estimado de creación: 10 minutos.', 'Our secret agent attempted an aerial infiltration using the ceiling fan blades as a landing platform. He is clinging with one hand to one of the blades, while his body dangles dangerously above the dining room table.' || char(10) || char(10) || 'Materials: a ceiling fan (switched off and with the switch locked) and a little adhesive putty to secure the elf''s hand to the blade. Make sure no one accidentally turns it on. Estimated creation time: 10 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(59, 'Atrapado en el Bote de Galletas', 'Trapped in the Cookie Jar', 'La glotonería ha tenido consecuencias catastróficas. El elfo se ha tirado de cabeza al tarro de las galletas y ahora solo se le ven las piernas y el trasero asomando, mientras sus brazos intentan desesperadamente alcanzar una galleta que está al fondo del recipiente de cristal.' || char(10) || char(10) || 'Solo necesitas un tarro de cristal transparente con galletas. Mete al elfo boca abajo de forma que las piernas queden rígidas hacia arriba. Es una de las escenas más graciosas y clásicas de la cocina. Tiempo estimado de creación: 5 minutos.', 'Gluttony has had catastrophic consequences. The elf dove headfirst into the cookie jar and now only his legs and bottom are visible sticking out, while his arms desperately try to reach a cookie at the bottom of the glass container.' || char(10) || char(10) || 'All you need is a transparent glass jar with cookies. Place the elf upside down so his legs stick straight up. It is one of the funniest and most classic kitchen scenes. Estimated creation time: 5 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(94, 'Duelo en la Tostadora de Acero', 'Duel in the Steel Toaster', '¡Situación de rehén! El elfo ha sido capturado por las pinzas de la tostadora mientras intentaba robar una miga de pan. Está medio metido en la ranura, con un tenedor de juguete en la mano intentando hacer palanca para liberarse antes de que alguien pulse el botón de inicio.' || char(10) || char(10) || 'Materiales: Tostadora (siempre desenchufada), un tenedor de plástico de juguete y algunas migas de pan esparcidas alrededor para dar contexto a su intento de robo. Tiempo estimado de creación: 5 minutos.', 'Hostage situation! The elf has been captured by the toaster while trying to steal a breadcrumb. He is halfway inside the slot, holding a toy fork and trying to lever himself free before someone presses the start button.' || char(10) || char(10) || 'Materials: a toaster (always unplugged), a plastic toy fork, and some breadcrumbs scattered around to give context to his attempted theft. Estimated creation time: 5 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(6, 'Secuestro por la Banda de los Dinosaurios', 'Kidnapped by the Dinosaur Gang', 'Los dinosaurios del niño se han rebelado contra la autoridad del Polo Norte. Han atado al elfo a las vías del tren de juguete con cuerdas de lana, y el tren está a solo unos centímetros de distancia. ¡Los niños deben resolver un acertijo para detener la locomotora a tiempo!' || char(10) || char(10) || 'Necesitarás trenes de juguete, figuras de dinosaurios, lana o cordel y una nota con una cuenta atrás o acertijo. Es una escena de acción trepidante para el cuarto de juegos. Tiempo estimado de creación: 20 minutos.', 'The child''s dinosaurs have rebelled against North Pole authority. They have tied the elf to the toy train tracks with yarn ropes, and the train is just a few centimetres away. The kids must solve a riddle to stop the locomotive in time!' || char(10) || char(10) || 'You will need toy trains, dinosaur figures, yarn or string, and a note with a countdown or riddle. It is a thrilling action scene for the playroom. Estimated creation time: 20 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(126, 'Cuidado con el Tiburón del Pasillo', 'Watch Out for the Hallway Shark', 'El elfo ha decidido que el pasillo es un océano peligroso y está intentando cruzarlo montado en un "bote" hecho con un zapato. Sin embargo, un tiburón de plástico le pisa los talones y está a punto de darle un mordisco a la popa de su embarcación.' || char(10) || char(10) || 'Materiales: Un zapato de adulto, una figura de tiburón (o una aleta hecha de cartulina gris) y papel de seda azul para simular el agua alrededor de la escena. Tiempo estimado de creación: 10 minutos.', 'The elf has decided the hallway is a dangerous ocean and is trying to cross it riding a "boat" made from a shoe. However, a plastic shark is hot on his heels and is about to take a bite out of the stern of his vessel.' || char(10) || char(10) || 'Materials: an adult shoe, a shark figure (or a fin made from grey cardstock), and blue tissue paper to simulate the water around the scene. Estimated creation time: 10 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"BATHROOM"},{"label":"MEDIUM"}]', 0),
(34, 'El Laberinto de Cubiertos Afilados', 'The Sharp Cutlery Labyrinth', 'En un alarde de temeridad, el elfo ha intentado cruzar el cajón de los cubiertos, pero se ha quedado atrapado entre los dientes de un tenedor gigante y el filo de una espátula. Sostiene un pequeño escudo hecho con un tapón de botella para protegerse del "metal frío".' || char(10) || char(10) || 'Abre ligeramente el cajón de los cubiertos de la cocina y coloca al elfo enredado entre las cucharas y tenedores. Usa un tapón de leche como escudo. Tiempo estimado de creación: 8 minutos.', 'In a daring display of recklessness, the elf tried to cross the cutlery drawer but got stuck between the prongs of a giant fork and the edge of a spatula. He is holding a small shield made from a bottle cap to protect himself from the "cold metal".' || char(10) || char(10) || 'Slightly open the kitchen cutlery drawer and place the elf tangled among the spoons and forks. Use a milk bottle cap as a shield. Estimated creation time: 8 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(78, 'Invasión de las Plantas Carnívoras', 'Invasion of the Carnivorous Plants', '¡La planta del salón ha cobrado vida! El elfo ha sido atrapado por las hojas de una maceta y parece que la planta está intentando "engullirlo". El elfo tiene una mano fuera pidiendo ayuda, mientras la otra sostiene un pequeño cuchillo de plástico para defenderse.' || char(10) || char(10) || 'Usa una planta de interior con hojas grandes (o una artificial). Envuelve al elfo entre las hojas y añade unos ojos de papel a la planta para que parezca un monstruo vegetal. Tiempo estimado de creación: 10 minutos.', 'The living room plant has come to life! The elf has been grabbed by the leaves of a potted plant and it looks like it is trying to "swallow" him. The elf has one hand sticking out asking for help, while the other holds a small plastic knife to defend himself.' || char(10) || char(10) || 'Use an indoor plant with large leaves (or an artificial one). Wrap the elf among the leaves and add paper eyes to the plant to make it look like a vegetable monster. Estimated creation time: 10 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"LIVINGROOM"},{"label":"MEDIUM"}]', 0),
(45, 'Atraco al Banco de Cerdito', 'Piggy Bank Heist', 'El elfo ha intentado un asalto de alto riesgo al hucha de cerdito de los niños. Se encuentra colgado de la ranura de las monedas, a punto de caer dentro del oscuro abismo lleno de ahorros, mientras intenta sacar un billete con un imán atado a un hilo.' || char(10) || char(10) || 'Materiales: Una hucha, un billete (real o de juguete), hilo y un pequeño imán o clip. Coloca al elfo con las piernas colgando dentro de la ranura para un efecto máximo de peligro. Tiempo estimado de creación: 12 minutos.', 'The elf has attempted a high-risk raid on the kids'' piggy bank. He is hanging from the coin slot, about to tumble into the dark savings-filled abyss, while trying to fish out a banknote with a magnet tied to a piece of string.' || char(10) || char(10) || 'Materials: a piggy bank, a note (real or toy), string, and a small magnet or paper clip. Place the elf with his legs dangling inside the coin slot for maximum danger effect. Estimated creation time: 12 minutes.', 'elf_danger', '[{"label":"DANGER"},{"label":"TREASURE"},{"label":"HARD"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(141, 'El Chef de los Huevos Sonrientes', 'The Smiley Egg Chef', '¡Alguien ha estado decorando el desayuno! El elfo ha asaltado la huevera del frigorífico y, con un rotulador mágico, ha dibujado caras divertidas, gafas y bigotes a todos los huevos. Se encuentra sentado en el borde de la caja, orgulloso de su nueva "pandilla" de amigos ovalados.' || char(10) || char(10) || 'Necesitarás una docena de huevos y un rotulador permanente (preferiblemente de punta fina). Dibuja expresiones diferentes en cada huevo y coloca al elfo sosteniendo el rotulador como si acabara de terminar su obra maestra. Tiempo estimado de creación: 15 minutos.', 'Someone has been decorating breakfast! The elf has raided the egg carton from the fridge and, with a magic marker, drawn funny faces, glasses, and moustaches on every single egg. He is sitting on the edge of the carton, proud of his new "gang" of oval friends.' || char(10) || char(10) || 'You will need a dozen eggs and a permanent marker (fine-tipped is best). Draw a different expression on each egg and place the elf holding the marker as if he has just finished his masterpiece. Estimated creation time: 15 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(46, 'Pesca de Manzanas en el Bol', 'Apple Bobbing in the Bowl', 'Inspirado por los juegos de feria, el elfo ha llenado un bol con agua y ha echado varias manzanas. Está intentando "pescarlas" desde el borde usando un tenedor como arpón, aunque parece que está a punto de perder el equilibrio y terminar dándose un chapuzón frutal.' || char(10) || char(10) || 'Materiales: Un bol grande con agua, 3 o 4 manzanas pequeñas y un tenedor de postre. Asegúrate de secar bien los pies del elfo después o usa cinta de doble cara para fijarlo al borde del recipiente. Tiempo estimado de creación: 5 minutos.', 'Inspired by fairground games, the elf has filled a bowl with water and tossed in several apples. He is trying to "catch" them from the rim using a fork as a harpoon, though he looks like he is about to lose his balance and end up taking a fruity plunge.' || char(10) || char(10) || 'Materials: a large bowl of water, 3 or 4 small apples, and a dessert fork. Make sure to dry the elf''s feet thoroughly afterwards, or use double-sided tape to fix him to the edge of the bowl. Estimated creation time: 5 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(13, 'El Tostador-Cama de Lujo', 'The Luxury Toaster Bed', '¿Quién necesita un sofá teniendo una tostadora caliente? El elfo ha metido un par de rebanadas de pan y las ha usado como colchón y manta para echarse una siesta. El olor a pan tostado parece ser su perfume favorito para dormir profundamente en mitad de la encimera.' || char(10) || char(10) || 'Necesitarás dos rebanadas de pan de molde tostadas (deja que se enfríen del todo antes de poner al elfo). Coloca una debajo y otra encima del elfo, asomando solo su cara por un lado. Tiempo estimado de creación: 8 minutos.', 'Who needs a sofa when you have a warm toaster? The elf has popped in a couple of bread slices and used them as a mattress and blanket for a nap. The smell of toast seems to be his favourite perfume for sleeping soundly in the middle of the kitchen counter.' || char(10) || char(10) || 'You will need two slices of toasted sandwich bread (let them cool completely before placing the elf). Put one underneath and one on top of the elf, with only his face peeking out from one side. Estimated creation time: 8 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"BEDROOM"},{"label":"EASY"}]', 0),
(49, 'Exprimida de Naranjas Gigante', 'Giant Orange Squeeze', '¡Operación Vitamina C en marcha! El elfo ha intentado hacer zumo para toda la familia, pero la naranja es casi tan grande como él. Se encuentra haciendo fuerza sobre el exprimidor manual, con la cara manchada de pulpa y rodeado de cáscaras por todas partes.' || char(10) || char(10) || 'Materiales: Un exprimidor manual, un par de naranjas cortadas y un vaso pequeño. Pon un poco de zumo real en el vaso para que la escena sea más auténtica y el niño pueda probarlo. Tiempo estimado de creación: 10 minutos.', 'Operation Vitamin C is underway! The elf has tried to make juice for the whole family, but the orange is almost as big as he is. He is straining over the manual juicer, his face splattered with pulp and surrounded by peel scattered everywhere.' || char(10) || char(10) || 'Materials: a manual juicer, a couple of halved oranges, and a small glass. Pour a little real juice in the glass to make the scene more authentic so the child can taste it. Estimated creation time: 10 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"FOOD"},{"label":"MEDIUM"}]', 0),
(12, 'Escalada al Tarro de las Chuches', 'Climbing to the Sweet Jar', 'El elfo ha divisado el botín prohibido: el tarro de las golosinas en lo alto de la estantería. Ha construido una escalera humana (o de utensilios) usando espátulas y cucharas de madera para alcanzar la cima y darse un festín de azúcar antes de que amanezca.' || char(10) || char(10) || 'Necesitarás varios utensilios de cocina largos y cinta adhesiva para unirlos formando una rampa o escalera. Apóyala contra el estante donde guardes los dulces y pon al elfo a mitad de camino. Tiempo estimado de creación: 15 minutos.', 'The elf has spotted the forbidden loot: the sweet jar at the top of the shelf. He has built a makeshift ladder using spatulas and wooden spoons to reach the top and treat himself to a sugar feast before dawn.' || char(10) || char(10) || 'You will need several long kitchen utensils and adhesive tape to join them into a ramp or ladder. Lean it against the shelf where you keep the sweets and place the elf halfway up. Estimated creation time: 15 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(14, 'Invasión de Hormigas de Chocolate', 'Chocolate Ant Invasion', '¡Un rastro sospechoso cruza la mesa! El elfo está dirigiendo una expedición de "hormigas" hechas de pepitas de chocolate que se dirigen directamente hacia el azucarero. Él va delante con una bandera, guiando a su ejército dulce hacia la victoria gastronómica.' || char(10) || char(10) || 'Materiales: Pepitas de chocolate o pasas, un azucarero y un palillo con un trozo de papel para la bandera. Coloca las pepitas en fila india haciendo curvas por la superficie de la cocina. Tiempo estimado de creación: 10 minutos.', 'A suspicious trail crosses the table! The elf is leading an expedition of chocolate chip "ants" heading straight for the sugar bowl. He is out front with a flag, guiding his sweet army toward gastronomic victory.' || char(10) || char(10) || 'Materials: chocolate chips or raisins, a sugar bowl, and a toothpick with a piece of paper for the flag. Arrange the chips in single file winding across the kitchen surface. Estimated creation time: 10 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(122, 'Lavandería de Cubiertos en el Lavavajillas', 'Cutlery Laundry in the Dishwasher', 'El elfo ha decidido que los cubiertos no estaban lo suficientemente limpios y se ha metido en el lavavajillas para darles un repaso manual. Está sentado en la cesta de los cubiertos con una esponja diminuta, frotando una cuchara como si fuera un espejo de plata.' || char(10) || char(10) || 'Abre el lavavajillas y coloca al elfo en el compartimento de los cubiertos. Necesitarás un trocito de esponja de cocina y un poco de jabón seco (solo para el efecto visual) sobre un plato cercano. Tiempo estimado de creación: 5 minutos.', 'The elf has decided the cutlery was not clean enough and climbed inside the dishwasher for a manual touch-up. He is sitting in the cutlery basket with a tiny sponge, scrubbing a spoon as if it were a silver mirror.' || char(10) || char(10) || 'Open the dishwasher and place the elf in the cutlery compartment. You will need a small piece of kitchen sponge and a little dry soap (just for the visual effect) on a nearby plate. Estimated creation time: 5 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"BATHROOM"},{"label":"EASY"}]', 0),
(127, 'El Laboratorio de la Pócima de Colores', 'The Colour Potion Laboratory', 'Algo extraño está pasando con la leche. El elfo ha sacado los colorantes alimentarios y está experimentando en un vaso, creando remolinos de colores psicodélicos. Parece un científico loco buscando la fórmula secreta para que la leche sepa a gominola.' || char(10) || char(10) || 'Necesitarás un vaso de leche y colorante alimentario líquido. Echa unas gotas de diferentes colores (no lo remuevas del todo) y pon al elfo sosteniendo el bote de colorante vacío. Tiempo estimado de creación: 5 minutos.', 'Something strange is happening with the milk. The elf has pulled out the food colouring and is experimenting in a glass, creating psychedelic swirls of colour. He looks like a mad scientist searching for the secret formula to make milk taste like gummy sweets.' || char(10) || char(10) || 'You will need a glass of milk and liquid food colouring. Drop in a few drops of different colours (do not stir fully) and place the elf holding the empty colouring bottle. Estimated creation time: 5 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(28, 'Nieve de Palomitas en el Microondas', 'Popcorn Snowfall in the Microwave', '¡Ha habido una explosión de nieve en la cocina! El elfo ha "olvidado" cerrar la bolsa de palomitas y ahora todo el interior del microondas (y parte del mostrador) está cubierto de palomitas blancas y esponjosas. Él está en medio, haciendo un ángel de nieve salado.' || char(10) || char(10) || 'Materiales: Un paquete de palomitas para microondas ya hechas. Espárcelas dentro del aparato y deja que algunas caigan hacia fuera. Coloca al elfo sentado sobre el plato giratorio. Tiempo estimado de creación: 10 minutos.', 'There has been a snow explosion in the kitchen! The elf "forgot" to close the popcorn bag and now the entire inside of the microwave (and part of the counter) is covered in fluffy white popcorn. He is in the middle, making a salty snow angel.' || char(10) || char(10) || 'Materials: a bag of already-made microwave popcorn. Scatter it inside the appliance and let some spill outward. Place the elf sitting on the turntable. Estimated creation time: 10 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"SNOW"},{"label":"MEDIUM"}]', 0),
(20, 'Atrapado en el Batidor de Varillas', 'Trapped in the Whisk', '¡Ayuda! El elfo intentó batir nata demasiado rápido y se ha quedado enredado entre las varillas metálicas. Sus piernas están cruzadas entre los alambres y sostiene un cuenco vacío sobre su cabeza como si fuera un casco de protección contra salpicaduras.' || char(10) || char(10) || 'Solo necesitas un batidor de varillas manual y un bol pequeño. Introduce con cuidado las piernas del elfo entre las varillas para que se sostenga por sí solo. Es una imagen visualmente muy impactante y divertida. Tiempo estimado de creación: 5 minutos.', 'Help! The elf tried to whip cream too fast and got tangled in the metal wires. His legs are crossed between the wires and he is holding an empty bowl on his head as if it were a splash-protection helmet.' || char(10) || char(10) || 'All you need is a manual whisk and a small bowl. Carefully thread the elf''s legs between the wires so he holds himself in place. It is a visually striking and very funny scene. Estimated creation time: 5 minutes.', 'elf_kitchen', '[{"label":"KITCHEN"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(145, 'El Mapa del Tesoro Envejecido', 'The Aged Treasure Map', '¡El elfo ha encontrado un mapa antiguo! Se le ve sosteniendo un papel amarillento con bordes quemados que muestra un dibujo de la planta de la casa. Una gran "X" roja marca un lugar secreto donde ha escondido un pequeño detalle para los niños.' || char(10) || char(10) || 'Para esta manualidad, dibuja un mapa simple de tu salón. Moja el papel con una bolsa de té húmeda para darle un tono antiguo y, una vez seco, quema con cuidado los bordes (¡con precaución!). Enrolla el mapa y ponlo en las manos del elfo. Tiempo estimado de creación: 15 minutos.', 'The elf has found an ancient map! He is seen holding a yellowed piece of paper with burnt edges showing a drawing of the house floor plan. A large red "X" marks a secret spot where he has hidden a little surprise for the kids.' || char(10) || char(10) || 'For this craft, draw a simple map of your living room. Dab the paper with a wet tea bag to give it an aged tone and, once dry, carefully singe the edges (with caution!). Roll the map up and place it in the elf''s hands. Estimated creation time: 15 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(44, 'Buceo en el Cofre de Joyas', 'Diving in the Jewellery Box', 'Nuestro aventurero ha asaltado el joyero de mamá o la caja de disfraces. Está sumergido hasta la cintura en una montaña de collares de perlas, pulseras brillantes y anillos de colores, sosteniendo un "diamante" (una piedra de cristal) como si fuera el mayor hallazgo del siglo.' || char(10) || char(10) || 'Solo necesitas colocar al elfo dentro de un joyero abierto. Enreda algunos collares a su alrededor para que parezca que está "nadando" entre joyas. Es una escena visualmente muy atractiva y brillante. Tiempo estimado de creación: 5 minutos.', 'Our adventurer has raided mum''s jewellery box or the dressing-up chest. He is submerged up to his waist in a mountain of pearl necklaces, glittering bracelets, and colourful rings, holding a "diamond" (a crystal stone) as if it were the greatest find of the century.' || char(10) || char(10) || 'All you need is to place the elf inside an open jewellery box. Tangle some necklaces around him to make it look like he is "swimming" among the jewels. It is a visually very attractive and sparkly scene. Estimated creation time: 5 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"CLOTHES"},{"label":"EASY"}]', 0),
(55, 'La Montaña de Monedas de Chocolate', 'The Chocolate Coin Mountain', '¡El botín dulce! El elfo ha construido una pirámide perfecta con monedas de chocolate dorado. Está sentado en la cima, protegiendo el tesoro con una espada hecha con un palillo de dientes y un trozo de papel de plata, desafiando a cualquiera que intente llevarse una pieza.' || char(10) || char(10) || 'Necesitarás una red de monedas de chocolate. Apílalas en forma de cono y coloca al elfo arriba. Puedes añadir un pequeño cartel que diga: "Solo para los que se hayan portado bien". Tiempo estimado de creación: 10 minutos.', 'Sweet loot! The elf has built a perfect pyramid with golden chocolate coins. He is sitting at the top, guarding the treasure with a sword made from a toothpick and a piece of silver foil, daring anyone who tries to take a piece.' || char(10) || char(10) || 'You will need a net of chocolate coins. Stack them in a cone shape and place the elf at the top. You can add a small sign reading: "Only for those who have behaved well". Estimated creation time: 10 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(90, 'X Marca el Lugar en la Nevera', 'X Marks the Spot on the Fridge', '¡El tesoro está bajo cero! El elfo ha pegado una gran "X" hecha con cinta aislante roja en la puerta de la nevera. Él está pegado justo al lado, señalando la marca con entusiasmo. Dentro de la nevera, en el lugar exacto tras la X, espera una sorpresa fresquita.' || char(10) || char(10) || 'Materiales: Cinta aislante o cartulina roja para la X. Dentro de la nevera puedes esconder un yogur especial, una chocolatina o incluso una pieza de fruta con una cara dibujada. Tiempo estimado de creación: 5 minutos.', 'The treasure is below zero! The elf has stuck a large "X" made from red insulating tape on the fridge door. He is fixed right next to it, enthusiastically pointing at the mark. Inside the fridge, right where the X is, a cool surprise is waiting.' || char(10) || char(10) || 'Materials: insulating tape or red cardstock for the X. Inside the fridge you can hide a special yoghurt, a chocolate bar, or even a piece of fruit with a face drawn on it. Estimated creation time: 5 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"KITCHEN"},{"label":"EASY"}]', 0),
(21, 'Pirata en Barco de Papel', 'Pirate on a Paper Boat', '¡Al abordaje! El elfo navega por las aguas del lavabo en un barco de papel hecho con papel de periódico. Lleva un parche en el ojo (dibujado o de papel) y busca el tesoro perdido en el fondo del océano (un anillo o una moneda en el desagüe).' || char(10) || char(10) || 'Haz un barco de papel clásico, pon al elfo dentro y coloca el barco en el lavabo seco o con un poco de algodón azul. No olvides el parche en el ojo para darle el toque pirata definitivo. Tiempo estimado de creación: 10 minutos.', 'All aboard! The elf is sailing the sink waters in a paper boat made from newspaper. He is wearing an eye patch (drawn or made from paper) and searching for the lost treasure at the bottom of the ocean (a ring or coin near the drain).' || char(10) || char(10) || 'Fold a classic paper boat, place the elf inside, and set the boat in the dry sink or on a little blue cotton. Don''t forget the eye patch to add the ultimate pirate touch. Estimated creation time: 10 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(104, 'Excavación Arqueológica en el Azucarero', 'Archaeological Dig in the Sugar Bowl', 'El elfo cree que hay diamantes ocultos en la cocina. Se le ha encontrado con una cuchara pequeña excavando en el azucarero, dejando un rastro de "arena blanca" por la encimera. Ha encontrado algunas cuentas de collar brillantes enterradas en el azúcar.' || char(10) || char(10) || 'Materiales: Un cuenco con azúcar, una cuchara de café y unas piedrecitas brillantes o cuentas de collar. Entierra los "tesoros" para que los niños puedan ayudarle a terminar la excavación. Tiempo estimado de creación: 10 minutos.', 'The elf believes there are diamonds hidden in the kitchen. He has been found with a tiny spoon digging in the sugar bowl, leaving a trail of "white sand" across the counter. He has already uncovered some sparkling beads buried in the sugar.' || char(10) || char(10) || 'Materials: a bowl of sugar, a coffee spoon, and some shiny pebbles or beads. Bury the "treasures" so the kids can help him finish the dig. Estimated creation time: 10 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"KITCHEN"},{"label":"MEDIUM"}]', 0),
(98, 'El Telescopio de Rollo de Papel', 'The Cardboard Roll Telescope', 'Desde lo alto de una estantería, el elfo vigila el horizonte. Está usando un rollo de papel higiénico vacío como telescopio, apuntando directamente hacia el árbol de Navidad, donde ha divisado un paquete que antes no estaba allí.' || char(10) || char(10) || 'Solo necesitas un rollo de cartón vacío. Pégalo a la cara del elfo con un poco de celo para que parezca que está mirando a través de él. Es una forma genial de dirigir la atención de los niños hacia un regalo específico. Tiempo estimado de creación: 5 minutos.', 'From the top of a shelf, the elf is scanning the horizon. He is using an empty toilet paper roll as a telescope, pointing it directly at the Christmas tree where he has spotted a package that was not there before.' || char(10) || char(10) || 'All you need is an empty cardboard roll. Attach it to the elf''s face with a bit of tape to make it look like he is peering through it. It is a great way to draw the kids'' attention toward a specific gift. Estimated creation time: 5 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"FESTIVAL"},{"label":"EASY"}]', 0),
(2, 'El Guardián de la Hucha', 'The Piggy Bank Guardian', '¡Intento de robo frustrado! El elfo ha pillado a otro juguete intentando abrir la hucha de los niños. Ahora, el elfo ha montado guardia encima del cerdito de ahorros, rodeándolo con una cadena (un collar de cuentas) y sosteniendo una llave de juguete.' || char(10) || char(10) || 'Usa la hucha de los niños, otro muñeco (como un dinosaurio o un coche) y al elfo encima de la hucha. Es una escena con mucha narrativa que enseña sobre el ahorro. Tiempo estimado de creación: 8 minutos.', 'Attempted robbery foiled! The elf has caught another toy trying to open the kids'' piggy bank. He has now mounted guard on top of the savings pig, surrounding it with a chain (a bead necklace) and holding a toy key.' || char(10) || char(10) || 'Use the kids'' piggy bank, another toy figure (like a dinosaur or a car), and the elf on top of the piggy bank. It is a scene with great narrative that also teaches about saving. Estimated creation time: 8 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"BEDROOM"},{"label":"MEDIUM"}]', 0),
(72, 'Láseres de Seguridad para el Botín', 'Security Lasers for the Loot', 'El elfo ha robado la caja de galletas y la ha protegido con un sistema de seguridad infrarrojo de alta tecnología. Ha cruzado hilos de lana roja por todo el mueble de la cocina para que nadie pueda acercarse a su tesoro sin activar la alarma.' || char(10) || char(10) || 'Necesitarás lana roja y celo. Cruza los hilos en zigzag delante de un armario o estante donde esté el "tesoro". El elfo debe estar sentado al final del laberinto, custodiando el premio. Tiempo estimado de creación: 20 minutos.', 'The elf has stolen the biscuit tin and protected it with a high-tech infrared security system. He has criss-crossed red yarn strings all across the kitchen cabinet so no one can get near his treasure without triggering the alarm.' || char(10) || char(10) || 'You will need red yarn and tape. Cross the strings in a zigzag in front of a cupboard or shelf where the "treasure" is. The elf should be sitting at the end of the maze, guarding the prize. Estimated creation time: 20 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"DANGER"},{"label":"HARD"}]', 0),
(115, 'Reparto de Pegatinas Brillantes', 'Shiny Sticker Giveaway', '¡Un tesoro compartido es mejor! El elfo ha abierto un sobre de pegatinas de estrellas doradas y se ha dedicado a pegarlas por toda su ropa y por la frente de los peluches cercanos. Ha dejado el resto de las pegatinas en un plato para que los niños se unan a la fiesta.' || char(10) || char(10) || 'Compra un sobre de pegatinas brillantes (estrellas, corazones o doradas). Pega unas cuantas en el traje del elfo y deja el paquete abierto a su lado. Es un "tesoro" muy fácil de gestionar y muy gratificante. Tiempo estimado de creación: 5 minutos.', 'Shared treasure is the best treasure! The elf has opened a packet of golden star stickers and gone about sticking them all over his outfit and on the foreheads of nearby stuffed animals. He has left the rest of the stickers on a plate so the kids can join in the fun.' || char(10) || char(10) || 'Buy a packet of shiny stickers (stars, hearts, or gold ones). Stick a few onto the elf''s outfit and leave the open packet beside him. It is a very easy and very rewarding "treasure". Estimated creation time: 5 minutes.', 'elf_treasure', '[{"label":"TREASURE"},{"label":"FESTIVAL"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(57, 'El Elfo Camuflado en los Cojines', 'The Elf Camouflaged in the Cushions', '¡El juego del escondite ha subido de nivel! El elfo se ha mimetizado con los cojines del sofá. Ha usado un trozo de tela del mismo color que el sofá para taparse hasta la nariz, dejando solo sus ojos traviesos a la vista. ¿Cuánto tardarán los niños en sentarse sobre él?' || char(10) || char(10) || 'Solo necesitas colocar al elfo entre dos cojines grandes y cubrirlo parcialmente con una manta o una funda de cojín similar. Es un reto de observación visual perfecto para empezar el día. Tiempo estimado de creación: 5 minutos.', 'Hide and seek has levelled up! The elf has blended in with the sofa cushions. He has used a piece of fabric matching the sofa colour to cover himself up to his nose, leaving only his mischievous eyes visible. How long will it take the kids to sit on him?' || char(10) || char(10) || 'All you need is to place the elf between two large cushions and partially cover him with a blanket or a similar cushion cover. It is a perfect visual observation challenge to start the day. Estimated creation time: 5 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"EASY"},{"label":"MYSTERY"}]', 0),
(108, 'Sesión de Yoga en la Alfombra', 'Yoga Session on the Rug', 'Namasté. El elfo ha decidido que necesita un poco de paz interior y ha montado un estudio de yoga en mitad de la alfombra. Está en la posición del "perro boca abajo" sobre una esterilla minúscula, rodeado de piedras decorativas que simulan un jardín zen.' || char(10) || char(10) || 'Materiales: Un trozo de goma eva o fieltro para la esterilla y unas piedras del jardín o velas pequeñas. Coloca al elfo en una postura flexible (sus brazos y piernas suelen ser perfectos para esto). Tiempo estimado de creación: 8 minutos.', 'Namasté. The elf has decided he needs a little inner peace and has set up a yoga studio in the middle of the rug. He is in the "downward dog" position on a tiny mat, surrounded by decorative stones simulating a zen garden.' || char(10) || char(10) || 'Materials: a piece of foam rubber or felt for the mat and some garden pebbles or small candles. Place the elf in a flexible pose (his arms and legs are usually perfect for this). Estimated creation time: 8 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"MEDIUM"},{"label":"FESTIVAL"}]', 0),
(51, 'El Escalador de la Cortina', 'The Curtain Climber', '¡Hazaña vertical! El elfo ha sido avistado a mitad de camino hacia el techo, escalando las cortinas del salón. Lleva una cuerda de seguridad y un pequeño saco a la espalda, como si estuviera intentando alcanzar la barra de la cortina para vigilar la calle desde lo más alto.' || char(10) || char(10) || 'Necesitarás una pinza de la ropa o un clip oculto tras la cortina para sujetar las manos del elfo a la tela. Usa un hilo de lana como cuerda de escalada que cuelgue hasta el suelo. Tiempo estimado de creación: 10 minutos.', 'Vertical feat! The elf has been spotted halfway up to the ceiling, climbing the living room curtains. He is wearing a safety rope and a small pack on his back, as if trying to reach the curtain rail to keep watch over the street from the very top.' || char(10) || char(10) || 'You will need a clothes peg or clip hidden behind the curtain to hold the elf''s hands to the fabric. Use a yarn string as a climbing rope hanging down to the floor. Estimated creation time: 10 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(149, 'Tarde de Película y Palomitas', 'Movie and Popcorn Afternoon', 'El elfo ha tomado el control del mando a distancia. Se le ha encontrado sentado en el reposabrazos del sofá, con el mando entre sus piernas y un cuenco gigante de palomitas (para él) listo para ver sus dibujos favoritos en la televisión.' || char(10) || char(10) || 'Deja el mando de la tele junto al elfo y un pequeño recipiente con palomitas reales. Si puedes dejar la televisión en el menú de una película navideña, el efecto será total. Tiempo estimado de creación: 5 minutos.', 'The elf has taken control of the remote. He has been found sitting on the sofa armrest, remote between his legs and a giant bowl of popcorn (just for him) ready to watch his favourite cartoons on the TV.' || char(10) || char(10) || 'Leave the TV remote next to the elf and a small bowl of real popcorn. If you can leave the television on the menu of a Christmas film, the effect will be complete. Estimated creation time: 5 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"FOOD"},{"label":"EASY"}]', 0),
(130, 'Concierto de Rock con la Guitarra', 'Rock Concert with the Guitar', '¡Hoy hay concierto en directo! El elfo ha encontrado una guitarra (o un ukelele) en el salón y se ha fabricado una púa con un trozo de cartón. Está dando un concierto exclusivo para los peluches, que están todos en primera fila con las manos arriba.' || char(10) || char(10) || 'Usa cualquier instrumento musical que tengas en el salón. Si no tienes, puede usar una raqueta de tenis como "air guitar". Coloca a otros juguetes alrededor como público entregado. Tiempo estimado de creación: 12 minutos.', 'Live concert tonight! The elf has found a guitar (or ukulele) in the living room and made himself a pick from a piece of cardboard. He is giving an exclusive concert for the stuffed animals, who are all in the front row with their hands in the air.' || char(10) || char(10) || 'Use any musical instrument you have in the living room. If you don''t have one, a tennis racket works perfectly as an "air guitar". Place other toys around as a devoted audience. Estimated creation time: 12 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"FESTIVAL"},{"label":"MEDIUM"}]', 0),
(60, 'El Elfo en el Columpio de Lámpara', 'The Elf on the Lamp Swing', '¡Diversión por todo lo alto! El elfo ha fabricado un columpio usando un rollo de cartón y un par de hilos largos, y lo ha colgado de la lámpara de pie del salón. Se balancea felizmente mientras observa el ajetreo de la casa desde el aire.' || char(10) || char(10) || 'Materiales: Un tubo de cartón de papel higiénico cortado por la mitad (como un asiento) y cordel. Ata el columpio a la lámpara (asegúrate de que esté apagada y sea estable). Tiempo estimado de creación: 15 minutos.', 'Fun at the very top! The elf has made a swing using a cardboard roll and a couple of long strings, and hung it from the floor lamp in the living room. He swings happily while watching all the activity in the house from up in the air.' || char(10) || char(10) || 'Materials: a toilet paper cardboard tube cut in half (as a seat) and string. Tie the swing to the lamp (make sure it is switched off and stable). Estimated creation time: 15 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"ADVENTURE"},{"label":"MEDIUM"}]', 0),
(56, 'Paseo en el Coche Teledirigido', 'Ride in the Remote-Control Car', '¡Velocidad extrema! El elfo ha "tomado prestado" el coche teledirigido de los niños y está haciendo un rally por la alfombra. Ha montado un circuito con obstáculos (libros, zapatos) y parece que está a punto de batir el récord de velocidad del pasillo.' || char(10) || char(10) || 'Usa un coche de juguete grande donde quepa el elfo. Coloca el mando del coche cerca de sus manos y crea un pequeño circuito de obstáculos por el suelo del salón. Tiempo estimado de creación: 10 minutos.', 'Extreme speed! The elf has "borrowed" the kids'' remote-control car and is doing a rally across the rug. He has set up an obstacle circuit (books, shoes) and looks like he is about to break the hallway speed record.' || char(10) || char(10) || 'Use a large toy car that the elf fits into. Place the car remote near his hands and create a small obstacle circuit on the living room floor. Estimated creation time: 10 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(24, 'Exposición de Arte en la Mesa', 'Art Exhibition on the Table', 'El elfo se siente artista. Ha sacado los folios y colores y ha dibujado retratos de toda la familia (con un estilo un poco abstracto). Los tiene todos expuestos en la mesa de centro como si fuera una galería de arte privada.' || char(10) || char(10) || 'Dibuja 3 o 4 dibujos rápidos "estilo elfo" (monigotes divertidos) y pon al elfo con un lápiz de color en la mano. Puedes poner un cartel que diga "Galería de Arte de Navidad". Tiempo estimado de creación: 20 minutos.', 'The elf is feeling artistic. He has pulled out some paper and coloured pencils and drawn portraits of the whole family (in a slightly abstract style). He has them all displayed on the coffee table as if it were a private art gallery.' || char(10) || char(10) || 'Draw 3 or 4 quick "elf-style" sketches (funny stick figures) and place the elf holding a coloured pencil. You can add a sign reading "Christmas Art Gallery". Estimated creation time: 20 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"EASY"}]', 0),
(8, 'Pesca de Peces de Papel', 'Paper Fish Fishing', 'El elfo ha convertido la pecera (o un bol con agua en el salón) en su lugar de pesca favorito. Con una caña hecha con un lápiz e hilo, está intentando pescar unos peces de colores que él mismo ha recortado de una revista.' || char(10) || char(10) || 'Materiales: Un lápiz, hilo, un clip doblado como anzuelo y peces de papel o cartulina. Pon un poco de celo en los peces para que se peguen al clip cuando los niños jueguen. Tiempo estimado de creación: 15 minutos.', 'The elf has turned the fish tank (or a bowl of water in the living room) into his favourite fishing spot. With a rod made from a pencil and string, he is trying to catch some colourful fish he has cut out from a magazine himself.' || char(10) || char(10) || 'Materials: a pencil, string, a bent paper clip as a hook, and paper or cardstock fish. Put a little tape on the fish so they stick to the clip when the kids play. Estimated creation time: 15 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"TREASURE"},{"label":"MEDIUM"}]', 0),
(9, 'Mensaje Secreto en el Marco de Fotos', 'Secret Message on the Photo Frame', '¡Hackeo de fotos! El elfo ha abierto un marco de fotos familiar y ha puesto un pequeño bigote y nariz de reno (de quita y pon) sobre el cristal de la foto de los niños. Está sentado sobre el marco, riéndose de su propia broma.' || char(10) || char(10) || 'Usa un rotulador de pizarra blanca (que se borra fácil del cristal) o recortes de papel con un poco de celo. Asegúrate de no dañar la foto original. Es una sorpresa muy graciosa al mirar las fotos de casa. Tiempo estimado de creación: 10 minutos.', 'Photo hack! The elf has opened a family photo frame and drawn a little moustache and reindeer nose (removable) on the glass over the kids'' photo. He is sitting on the frame, laughing at his own prank.' || char(10) || char(10) || 'Use a whiteboard marker (which wipes off glass easily) or paper cut-outs with a little tape. Make sure not to damage the original photo. It is a very funny surprise when you look at the photos around the house. Estimated creation time: 10 minutes.', 'elf_livingroom', '[{"label":"LIVINGROOM"},{"label":"MYSTERY"},{"label":"EASY"}]', 0);
INSERT INTO elf_adventures (id, title, title_en, description, description_en, imageRes, tags, isFavorite) VALUES
(109, 'Baño de Burbujas de Algodón', 'Cotton Bubble Bath', '¡Relax total! El elfo ha llenado el lavabo hasta arriba con bolas de algodón blanco para simular una bañera de espuma gigante. Está sumergido cómodamente, con un patito de goma al lado y una toallita minúscula enrollada en la cabeza.' || char(10) || char(10) || 'Solo necesitas un paquete de bolas de algodón y el lavabo (asegúrate de que esté seco). Coloca al elfo en medio y añade algún juguete de baño pequeño para completar la escena. Tiempo estimado de creación: 5 minutos.', 'Total relaxation! The elf has filled the sink to the brim with white cotton balls to simulate a giant bubble bath. He is comfortably submerged, with a rubber duck beside him and a tiny towel wrapped around his head.' || char(10) || char(10) || 'All you need is a pack of cotton balls and the sink (make sure it is dry). Place the elf in the middle and add a small bath toy to complete the scene. Estimated creation time: 5 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"EASY"}]', 0),
(23, 'Mensaje en el Espejo Empañado', 'Message on the Steamed Mirror', 'El elfo ha dejado un mensaje secreto que solo aparece cuando alguien se ducha. Ha escrito "¡Santa te vigila!" o ha dibujado un árbol de Navidad en el espejo usando un poco de vaho mágico (o jabón).' || char(10) || char(10) || 'Para este truco, escribe en el espejo seco con un bastoncillo mojado en un poco de jabón líquido transparente. Al secarse no se verá, pero cuando el baño se llene de vapor, el mensaje aparecerá por arte de magia. Tiempo estimado de creación: 5 minutos.', 'The elf has left a secret message that only appears when someone showers. He has written "Santa is watching you!" or drawn a Christmas tree on the mirror using a little magic steam (or soap).' || char(10) || char(10) || 'For this trick, write on the dry mirror with a cotton bud dipped in a little clear liquid soap. Once dry it will be invisible, but when the bathroom fills with steam, the message will appear as if by magic. Estimated creation time: 5 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"MYSTERY"},{"label":"MEDIUM"}]', 0),
(140, 'Rápel de Papel Higiénico', 'Toilet Paper Abseil', '¡Aventura vertical! El elfo ha decidido bajar desde el toallero hasta el suelo usando una larga tira de papel higiénico como cuerda de escalada. Está a mitad de camino, sujeto con fuerza, en una maniobra de descenso digna de un comando.' || char(10) || char(10) || 'Desenrolla una tira larga de papel higiénico desde el soporte y asegura al elfo a ella usando un clip o un poco de celo por detrás. Es una imagen muy impactante y sencilla de hacer. Tiempo estimado de creación: 5 minutos.', 'Vertical adventure! The elf has decided to descend from the towel rail to the floor using a long strip of toilet paper as a climbing rope. He is halfway down, gripping tightly, in a descent manoeuvre worthy of a commando.' || char(10) || char(10) || 'Unroll a long strip of toilet paper from the holder and secure the elf to it using a clip or a little tape on the back. It is a very striking and simple scene to set up. Estimated creation time: 5 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"ADVENTURE"},{"label":"EASY"}]', 0),
(27, 'Pesca de Peces en el Inodoro', 'Toilet Fishing', '¡Peligro, pescador a bordo! El elfo se ha sentado en el borde del inodoro con una caña de pescar hecha con un lápiz e hilo dental. En el extremo del hilo, ha pescado un pececito de gominola o de papel que "nadaba" en las aguas claras.' || char(10) || char(10) || 'Usa un lápiz como caña e hilo dental. Puedes pegar un pez de plástico o papel al hilo. ¡Importante! Asegúrate de que el elfo esté bien sujeto para que no acabe dándose un chapuzón real. Tiempo estimado de creación: 10 minutos.', 'Danger, fisherman on board! The elf has perched on the edge of the toilet with a fishing rod made from a pencil and dental floss. At the end of the line, he has caught a gummy or paper fish that was "swimming" in the clear water.' || char(10) || char(10) || 'Use a pencil as the rod and dental floss as the line. You can attach a plastic or paper fish to the end. Important: make sure the elf is well secured so he does not end up taking a real dip. Estimated creation time: 10 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0),
(36, 'Disfraz de Momia de Papel', 'Toilet Paper Mummy Costume', 'El elfo se ha pasado con el papel higiénico y ha terminado completamente enrollado en él. Parece una pequeña momia navideña que vigila desde la encimera, y solo se le ven sus ojos brillantes asomando por una rendija.' || char(10) || char(10) || 'Envuelve al elfo con cuidado usando tiras de papel higiénico, como si fuera una venda. Puedes usar un par de puntos de celo para que no se desenrolle. Déjalo junto al portacepillos. Tiempo estimado de creación: 10 minutos.', 'The elf got a bit carried away with the toilet paper and ended up completely wrapped in it. He looks like a tiny Christmas mummy keeping watch from the counter, with only his bright eyes peeking through a gap.' || char(10) || char(10) || 'Carefully wrap the elf using strips of toilet paper, as if bandaging him. You can use a couple of small pieces of tape to stop it unravelling. Leave him next to the toothbrush holder. Estimated creation time: 10 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"EASY"}]', 0),
(58, 'Guerra de Pasta de Dientes', 'Toothpaste War', '¡Alguien ha apretado demasiado el tubo! El elfo ha dejado un rastro de pasta de dientes azul o blanca por el lavabo y ha dibujado "estrellas" con ella. Se le ve con el tapón en la mano, como si estuviera intentando ocultar las pruebas del desastre.' || char(10) || char(10) || 'Usa un poco de pasta de dientes real para crear dibujos simples en el lavabo o sobre una servilleta. Coloca al elfo "manchado" con una pizca de pasta en el traje. Se limpia fácil con agua. Tiempo estimado de creación: 5 minutos.', 'Someone squeezed the tube too hard! The elf has left a trail of blue or white toothpaste across the sink and drawn "stars" with it. He is seen holding the cap, as if trying to hide the evidence of the disaster.' || char(10) || char(10) || 'Use a little real toothpaste to create simple drawings in the sink or on a napkin. Place the elf "stained" with a tiny dab of paste on his outfit. It wipes off easily with water. Estimated creation time: 5 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0),
(63, 'Paseo en Barco de Jabonera', 'Sailing in the Soap Dish Boat', 'El elfo ha convertido la jabonera en su barco personal. Navega por la encimera del baño, rodeado de "olas" hechas con toallas azules, buscando el tesoro que se esconde detrás del bote de colonia.' || char(10) || char(10) || 'Usa una jabonera de plástico o madera y coloca al elfo dentro. Usa toallas de color azul o papel de seda para simular el mar alrededor. Es una escena muy creativa. Tiempo estimado de creación: 10 minutos.', 'The elf has turned the soap dish into his personal boat. He is sailing across the bathroom counter, surrounded by "waves" made from blue towels, searching for the treasure hidden behind the cologne bottle.' || char(10) || char(10) || 'Use a plastic or wooden soap dish and place the elf inside. Use blue towels or tissue paper to simulate the sea around him. It is a very creative scene. Estimated creation time: 10 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"TREASURE"},{"label":"MEDIUM"}]', 0),
(71, 'Taller de Maquillaje de Navidad', 'Christmas Make-Up Workshop', 'El elfo ha asaltado el neceser y se ha pintado una nariz roja como la de Rudolph usando un poco de pintalabios. También ha intentado maquillar a los cepillos de dientes, poniéndoles lacitos o colores brillantes.' || char(10) || char(10) || 'Usa un poco de colorete o pintalabios (que sea fácil de quitar) para marcar la nariz del elfo. Pon un par de pinceles de maquillaje a su alrededor para decorar la escena. Tiempo estimado de creación: 10 minutos.', 'The elf has raided the toiletry bag and painted himself a red nose just like Rudolph''s using a bit of lipstick. He has also tried to make up the toothbrushes, adding little bows and bright colours to them.' || char(10) || char(10) || 'Use a little blusher or lipstick (easy to remove) to mark the elf''s nose. Place a couple of make-up brushes around him to decorate the scene. Estimated creation time: 10 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"CLOTHES"},{"label":"MEDIUM"}]', 0),
(7, 'Esquí Acuático con Cepillos de Dientes', 'Water Skiing with Toothbrushes', '¡Acción extrema! El elfo está usando dos cepillos de dientes como esquís y se desliza por la rampa del lavabo. Está sujetando el hilo dental como si fuera la cuerda de un barco que lo arrastra a toda velocidad.' || char(10) || char(10) || 'Coloca los pies del elfo sobre las cerdas de dos cepillos de dientes. Usa un trozo largo de hilo dental atado a un grifo para que parezca que está esquiando de verdad. Tiempo estimado de creación: 15 minutos.', 'Extreme action! The elf is using two toothbrushes as water skis and gliding down the slope of the sink. He is gripping the dental floss as if it were a tow rope pulling him along at full speed.' || char(10) || char(10) || 'Place the elf''s feet on the bristles of two toothbrushes. Use a long piece of dental floss tied to a tap to make it look like he is genuinely skiing. Estimated creation time: 15 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"ADVENTURE"},{"label":"HARD"}]', 0),
(29, 'Atrapado en el Rollo Infinito', 'Trapped in the Endless Roll', '¡Socorro! El elfo ha empezado a rodar por el pasillo dentro de un rollo de papel higiénico y ha dejado un rastro de metros y metros de papel por todo el suelo del baño. Se encuentra al final del camino, mareado y enredado entre las hojas blancas.' || char(10) || char(10) || 'Desenrolla una buena cantidad de papel higiénico creando un camino desde el soporte hasta la puerta. Pon al elfo al final, envuelto en el último trozo de papel. ¡A los niños les encanta el caos controlado! Tiempo estimado de creación: 10 minutos.', 'Help! The elf started rolling down the hallway inside a toilet paper roll and has left a trail of metres and metres of paper all over the bathroom floor. He is at the very end of the trail, dizzy and tangled in the white sheets.' || char(10) || char(10) || 'Unroll a generous length of toilet paper creating a path from the holder to the door. Place the elf at the end, wrapped in the last piece of paper. Kids absolutely love controlled chaos! Estimated creation time: 10 minutes.', 'elf_bathroom', '[{"label":"BATHROOM"},{"label":"DANGER"},{"label":"MEDIUM"}]', 0);
